window.ACADEMY={"lessons":[{"id":"l1","cat":"Начало смены","title":"Открытие ПВЗ","summary":"Подготовка пункта к работе с клиентами и поставками.","steps":["Придите к началу смены и проверьте доступность помещения и оборудования.","Убедитесь, что рабочее место, клиентская зона и примерочные чистые.","Проверьте интернет, сканер, компьютер и работу камер наблюдения.","Авторизуйтесь в WB ПВЗ под своей учётной записью.","Проверьте сообщения программы, поступившие поставки и незавершённые операции."],"notes":"Не используйте чужие учётные данные. О проблемах, мешающих работе, сообщайте ответственному.","quiz":[{"q":"В начале смены сканер не работает. Как поступить?","options":["Проверить оборудование и устранить проблему до операций","Продолжить приёмку, считая все товары принятыми","Выдать клиенту заказ без проверки в программе","Отключить камеры и начать работу"],"answer":0,"explanation":"Проверить оборудование и устранить проблему до операций. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Подготовка пункта к работе с клиентами и поставками.","check":"Проверьте, что рабочее место готово и выбран правильный пункт выдачи."},{"id":"l2","cat":"Начало смены","title":"Распорядок дня","summary":"Повторяющиеся действия в течение смены.","steps":["Принимайте поступающие поставки и размещайте товары по ячейкам.","Выдавайте заказы и оформляйте отказы строго через программу.","Следите за курьерскими заказами и возвратами.","Регулярно проверяйте примерочные, склад и клиентскую зону.","Проводите переупаковку и формируйте возвратные коробки по требованиям программы.","Перед закрытием проверьте незавершённые операции и состояние ПВЗ."],"notes":"Указанные действия дополняют, но не заменяют текущие задания в WB ПВЗ.","quiz":[{"q":"В течение смены накопились товары к возврату. Что делать?","options":["Оформить переупаковку и возвратные коробки по программе","Сложить их вместе с заказами к выдаче","Оставить их без учёта до следующего месяца","Отправить их без маркировки"],"answer":0,"explanation":"Оформить переупаковку и возвратные коробки по программе. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Повторяющиеся действия в течение смены.","check":"Проверьте, что рабочее место готово и выбран правильный пункт выдачи."},{"id":"l3","cat":"Начало смены","title":"Чистота и порядок","summary":"Практический чек-лист уборки.","steps":["Мойте полы не менее двух раз в день с учётом загрязнения.","Протирайте коврики, зеркала и контактные поверхности ориентировочно каждые 2–3 часа.","Проверяйте примерочную после каждого клиента.","Убирайте влагу и грязь с учётом сезона.","Следите за состоянием штор, мебели и зоны выдачи."],"notes":"Периодичность взята из присланных учебных памяток; актуальные требования к состоянию ПВЗ сверяйте с регламентом.","quiz":[{"q":"После клиента примерочная загрязнена. Что правильно?","options":["Проверить и привести примерочную в порядок","Ждать общей уборки в конце недели","Закрыть примерочную без проверки","Попросить следующего клиента убрать"],"answer":0,"explanation":"Проверить и привести примерочную в порядок. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Практический чек-лист уборки.","check":"Проверьте, что рабочее место готово и выбран правильный пункт выдачи."},{"id":"l4","cat":"Начало смены","title":"Перерыв одного сотрудника","summary":"Как временно закрыть ПВЗ, если работаете в одиночку.","steps":["При необходимости краткого перерыва подготовьте объявление формата А4 с временем отсутствия.","Разместите объявление на видном месте под камерой.","Не превышайте предусмотренный инструкцией перерыв до 15 минут.","Вернувшись, снимите объявление и возобновите работу."],"notes":"Правило относится к описанному в обучающих материалах сценарию. Проверяйте актуальные ограничения.","quiz":[{"q":"Сотрудник работает один и ему нужен разрешённый короткий перерыв. Что подготовить?","options":["Объявление с временем отсутствия на видном месте","Только сообщение в личный чат","Закрыть ПВЗ без информации для клиентов","Сменить статус всех товаров на возврат"],"answer":0,"explanation":"Объявление с временем отсутствия на видном месте. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как временно закрыть ПВЗ, если работаете в одиночку.","check":"Проверьте, что рабочее место готово и выбран правильный пункт выдачи."},{"id":"l5","cat":"Начало смены","title":"Вход в программу WB ПВЗ и выбор пункта","summary":"Первичная авторизация, выбор своего ПВЗ, ПИН-код и восстановление доступа.","steps":["Перед входом убедитесь, что руководитель зарегистрировал ваш номер телефона как сотрудника нужного ПВЗ в WB Point. Без этого ваш профиль может не появиться в списке.","Откройте десктоп-приложение WB ПВЗ, введите собственный номер телефона и нажмите «Отправить код в приложение».","Откройте клиентское приложение Wildberries на своём телефоне, найдите push-уведомление с кодом и введите его в WB ПВЗ. Код не сообщайте другим людям.","Выберите пункт выдачи из списка. Для поиска используйте ID ПВЗ или адрес. Проверьте, что выбрали именно тот пункт, где работаете, а не другой.","Выберите своё имя в списке сотрудников. Если имени нет, обратитесь к руководителю для проверки регистрации и привязки.","При предложении быстрого входа придумайте ПИН-код, нажмите «Установить», повторите его и нажмите «Подтвердить». Подтвердите установку кодом из клиентского приложения Wildberries.","При следующем входе используйте собственный ПИН-код. Для смены сотрудника выйдите из текущего аккаунта и войдите под своим профилем.","Если забыли ПИН-код, нажмите «Не помню код», укажите телефон, получите push-код в Wildberries, выберите своё имя и установите новый ПИН-код с подтверждением.","После входа проверьте выбранный ПВЗ. Основные вкладки: «Выдача», «Приёмка», «Возврат», «Доставки», «Ещё». Смена пункта выполняется через меню «Смена ПВЗ»."],"notes":"Код входа в программу и код для выдачи заказа курьеру — разные вещи. Не используйте QR-код курьера для авторизации. Интерфейс и способы входа могут обновляться.","quiz":[{"q":"После ввода телефона WB ПВЗ просит код. Откуда его взять?","options":["Из push-уведомления в клиентском приложении Wildberries","Из кода курьера в меню выдачи","Из штрихкода товара на коробке","Из TRBX возвратной коробки"],"answer":0,"explanation":"Из push-уведомления в клиентском приложении Wildberries. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Сотрудник открыл WB ПВЗ и хочет начать приёмку. Где находится нужный раздел?","options":["Во вкладке «Приёмка», пункт «Товары»","Во вкладке «Выдача», пункт «Код курьера»","Во вкладке «Возврат», пункт «Коробки»"],"answer":0,"explanation":"Для обычной приёмки откройте «Приёмка» → «Товары»."},{"q":"Для чего нужны вкладки «Выдача», «Приёмка», «Возврат»?","options":["Это разные способы входа в один список","Они разделяют операции по выдаче, поступлению и возврату","Они переключают разные пункты выдачи"],"answer":1,"explanation":"Каждая вкладка содержит свой рабочий процесс и собственное боковое меню."},{"q":"Вы вошли в WB ПВЗ, но в списке нет нужного пункта. Как действовать?","options":["Продолжить в любом доступном ПВЗ","Проверить, что ваш номер зарегистрирован в WB Point для нужного ПВЗ, и обратиться к руководителю","Попросить QR-код выдачи курьеру","Оформить выдачу в другом пункте"],"answer":1,"explanation":"Профиль сотрудника и доступ к нужному ПВЗ настраиваются руководителем; курьерский QR-код не является способом входа."},{"q":"После входа отображается другой ПВЗ. Что сделать до начала операций?","options":["Продолжить: ПВЗ не влияет на операции","Выбрать правильный ПВЗ и проверить профиль сотрудника","Очистить историю браузера","Переключиться в раздел «Возврат»"],"answer":1,"explanation":"Операции должны проводиться в рабочем окне нужного пункта и под своим профилем."}],"role":"Сотрудник","version":"","when":"Первичная авторизация, выбор своего ПВЗ, ПИН-код и восстановление доступа.","check":"После входа в шапке программы убедитесь, что выбран нужный ПВЗ и ваш профиль сотрудника. Не используйте для входа код выдачи курьеру."},{"id":"l6","cat":"Приёмка и склад","title":"Приёмка поставки","summary":"От получения коробки до размещения товара.","steps":["Перейдите в верхнюю вкладку «Приёмка». В левом меню выберите «Товары» — здесь начинается обычная приёмка поставки.","Подготовьте сканер и найдите QR-код на поступившем грузовом месте или товаре, который программа просит отсканировать.","Сканируйте код и внимательно прочитайте ответ программы. Не считайте товар принятым только потому, что сканер подал звуковой сигнал.","Если система просит уточнить ячейку, выберите фактическое место размещения. Не назначайте ячейку, в которой товара нет.","При расхождении количества, повреждении или отсутствии нужного кода остановитесь на проблемной позиции, зафиксируйте обстоятельства и действуйте по подсказке программы или регламенту.","После приёмки проверьте, что товары отражены в программе и физически размещены в назначенных ячейках.","После каждого сканирования смотрите на сообщение программы: успешное считывание сканером и подтверждённая приёмка — не одно и то же.","Если товар отсутствует физически или поступил повреждённым, не подтверждайте приёмку без проверки ситуации; зафиксируйте расхождение и используйте предусмотренный процесс."],"notes":"Не подтверждайте получение товаров, которые фактически не поступили.","quiz":[{"q":"Сканер издал сигнал, но программа не показала приёмку. Что делать?","options":["Проверить сообщение программы и завершённость операции","Считать товар принятым только по звуку","Сразу отправить товар на возврат","Удалить товар из списка поставки"],"answer":0,"explanation":"Проверить сообщение программы и завершённость операции. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Поставка приехала, сканер подал сигнал, но товар не появился в программе. Что делать?","options":["Считать товар принятым и разместить","Повторить все сканирования без проверки","Проверить ответ программы и завершение операции"],"answer":2,"explanation":"Звуковой сигнал сканера не подтверждает приёмку. Нужно увидеть результат в WB ПВЗ."},{"q":"Система показывает одну ячейку, а сотрудник кладёт товар в другую. Что нужно сделать?","options":["Привести фактическое размещение и учёт ячейки в соответствие","Оставить как есть, если товар легко найти","Записать место на бумаге и не менять данные"],"answer":0,"explanation":"Ячейка в программе должна соответствовать фактическому расположению товара."},{"q":"В каком разделе начинается обычная приёмка поставки?","options":["«Выдача» → «Товары»","«Возврат» → «Коробки»","«Приёмка» → «Товары»","«Доставки» → «WB Track»"],"answer":2,"explanation":"Для обычной поставки используется вкладка «Приёмка» и пункт «Товары»."},{"q":"Сканер не распознал код грузового места. Что правильно сделать?","options":["Подтвердить приёмку вручную без проверки","Проверить читаемость кода и тип сканируемого объекта, затем повторить сканирование","Сразу поместить груз в возвратную коробку","Выдать груз курьеру"],"answer":1,"explanation":"Нельзя подтверждать приёмку, не установив, что именно принимает программа."}],"role":"Сотрудник","version":"","when":"От получения коробки до размещения товара.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l7","cat":"Приёмка и склад","title":"Организация склада","summary":"Как быстро находить заказы и снижать потери.","steps":["Разделяйте хранение по предусмотренным ячейкам, полкам и зонам.","Сканируйте перемещение товара в ячейку, когда это предусмотрено программой.","Не закрывайте доступ к пожарным выходам и оборудованию.","Крупногабаритные товары размещайте отдельно по правилам.","Не смешивайте товары, подготовленные к возврату, с заказами к выдаче."],"notes":"","quiz":[{"q":"Товар положили не в ту ячейку, что указана в системе. Как действовать?","options":["Привести физическое размещение и данные ячейки в соответствие","Оставить как есть до следующей инвентаризации","Считать любую свободную ячейку правильной","Положить другой товар на его место"],"answer":0,"explanation":"Привести физическое размещение и данные ячейки в соответствие. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как быстро находить заказы и снижать потери.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l8","cat":"Приёмка и склад","title":"Поиск товара по ШК","summary":"Как найти заказ через десктопную программу.","steps":["Откройте боковое меню WB ПВЗ и выберите «Информация о товаре». Этот инструмент помогает узнать текущее состояние конкретного товара.","Отсканируйте ШК товара в поле поиска. Если требуется, используйте поиск по баркоду.","В открывшейся карточке проверьте статус, штрихкод, баркод, указанную ячейку и возвратную коробку, если она назначена.","Вкладка «История статусов» показывает, что происходило с товаром; «О товаре» — основные сведения; «О возврате» — сведения о возвратной операции.","Если вопрос связан с браком, откройте «Об отметке брака»; если товар не удаётся найти в ожидаемой ячейке — «История изменения ячейки».","Сопоставьте данные программы с реальным товаром. Не меняйте статус или ячейку наугад только ради совпадения данных.","Откройте главное меню и выберите «Информация о товаре». Введите ШК или баркод и выполните поиск.","В найденной карточке проверьте статус товара, его ШК, баркод, коробку и ячейку.","Для поиска причины расхождения откройте нужную вкладку: «История статусов», «О товаре», «О возврате», «Об отметке брака» или «История изменения ячейки»."],"notes":"Сверяйте ШК или баркод перед тем, как делать вывод о статусе или местонахождении товара. История изменения ячейки помогает восстановить перемещения, но сама по себе не доказывает физическое наличие товара.","quiz":[{"q":"Нужно выяснить, где раньше находился товар. Какую вкладку открыть?","options":["«История изменения ячейки»","«О возврате»","«Об отметке брака»","«О товаре»"],"answer":0,"explanation":"«История изменения ячейки». Сверьте ответ с порядком действий, разобранным выше."},{"q":"Товар не нашли в ожидаемой ячейке. Какую вкладку карточки товара проверить?","options":["«Об отметке брака»","«История изменения ячейки»","«О возврате»"],"answer":1,"explanation":"История изменения ячейки показывает, где товар числился раньше."},{"q":"Клиент спорит, что товар уже был возвращён. Где посмотреть данные операции?","options":["«О возврате» и «История статусов»","Только «Об отметке брака»","Только «История изменения ячейки»"],"answer":0,"explanation":"Карточка товара содержит отдельные сведения о возврате и историю статусов."},{"q":"Где посмотреть историю перемещения товара между ячейками?","options":["«Выдача» → «Выдать все»","«Информация о товаре» → «История изменения ячейки»","«Возврат» → «Картон»","«Доставки» → «Новая коробка»"],"answer":1,"explanation":"В карточке найденного по ШК товара предусмотрена отдельная вкладка истории изменения ячейки."},{"q":"В карточке найден статус товара, но физически его нет на полке. Что делать?","options":["Считать товар найденным по данным карточки","Сверить ШК и историю ячейки, затем продолжить поиск по установленной процедуре","Немедленно выдать его клиенту","Поменять статус без поиска"],"answer":1,"explanation":"Данные карточки помогают искать товар, но не подтверждают его физическое наличие."}],"role":"Сотрудник","version":"","when":"Как найти заказ через десктопную программу.","check":"Убедитесь, что карточка относится к нужному ШК или баркоду; сопоставьте статус, ячейку и историю перемещений."},{"id":"l9","cat":"Приёмка и склад","title":"Инвентаризация","summary":"Проверка фактических остатков.","steps":["Запустите инвентаризацию в доступной версии WB ПВЗ.","Последовательно просканируйте все товары, числящиеся на ПВЗ.","Разберите расхождения и найдите неотсканированные позиции.","Завершите проверку в установленный срок."],"notes":"В присланных материалах: инвентаризация не реже раза в 30 дней; на завершение отводится 24 часа. Сверяйте с актуальными правилами.","quiz":[{"q":"При инвентаризации обнаружено расхождение. Что важно?","options":["Проверить фактическое наличие и зафиксировать расхождение по процедуре","Подтвердить все позиции как найденные","Удалить результаты предыдущей проверки","Перенести все товары в одну ячейку"],"answer":0,"explanation":"Проверить фактическое наличие и зафиксировать расхождение по процедуре. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Проверка фактических остатков.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l10","cat":"Выдача клиенту","title":"Обычная выдача заказа","summary":"Проверка клиента, товара и завершение операции.","steps":["Откройте верхнюю вкладку «Выдача» и попросите клиента показать QR-код заказа в приложении Wildberries. При необходимости используйте предусмотренный программой поиск по последним четырём цифрам телефона.","Сканируйте клиентский QR-код и дождитесь загрузки списка заказов. Не выдавайте товары до появления заказа в программе.","Найдите товары по назначенным ячейкам. Сверьте штрихкоды фактических товаров с теми, которые ожидает программа.","Передайте товар клиенту для осмотра или примерки, если это предусмотрено для заказа. Уточните, какие позиции клиент забирает, а от каких отказывается.","Для каждой позиции используйте предусмотренные кнопки «Выдать» или «Отменить»; для групповых действий — «Выдать все» или «Отменить все», только если это соответствует решению клиента.","Обратите внимание на оплату: зелёный статус указывает на оплаченный товар, красный — на неоплаченный. При проблеме с оплатой не завершайте выдачу вопреки статусу программы.","Завершите операцию в WB ПВЗ и убедитесь, что статус изменился. Физическая передача товара без подтверждения в программе не завершает выдачу.","В верхнем меню откройте «Выдача». Попросите покупателя показать QR-код в приложении Wildberries или воспользуйтесь предусмотренным способом поиска по последним четырём цифрам телефона.","Проверьте список заказов и их оплату: зелёная отметка относится к оплаченным товарам, красная — к неоплаченным.","Найдите товары в указанных ячейках, проверьте соответствие выдаваемых вещей заказу и только затем завершите выдачу в программе.","Если покупатель отказывается от части товаров, оформите отказ в программе; не отмечайте отказанный товар как выданный."],"notes":"Клиентский QR-код обновляется ежедневно; ориентируйтесь на актуальный код в приложении клиента.","quiz":[{"q":"Клиент отказывается от одного из нескольких заказов. Что делать?","options":["Оформить отказ именно от этой позиции в программе","Нажать «Выдать все» для всех позиций","Отдать товар без изменения статуса","Перевести весь заказ в возвратную коробку"],"answer":0,"explanation":"Оформить отказ именно от этой позиции в программе. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Клиент хочет забрать одну позицию и отказаться от другой. Как оформить?","options":["Нажать «Выдать все»","Оформить каждую позицию по решению клиента","Нажать «Отменить все»"],"answer":1,"explanation":"Используйте «Выдать» и «Отменить» для конкретных позиций, не применяйте массовое действие без основания."},{"q":"Товар передан клиенту, но выдача в программе не подтверждена. Что неверно?","options":["Ничего, достаточно физической передачи","Нужно завершить выдачу в WB ПВЗ и проверить статус","Можно подтвердить позже без проверки"],"answer":1,"explanation":"Физическая передача не заменяет регистрацию выдачи в рабочей программе."},{"q":"На экране выдачи есть заказ, но нужный товар физически не найден. Что делать?","options":["Нажать «Выдать» и искать позже","Не подтверждать выдачу; действовать по процедуре поиска отсутствующего товара","Заменить товар другим похожим","Оформить возврат без клиента"],"answer":1,"explanation":"Выдача в программе должна соответствовать фактической передаче товара."},{"q":"Какой способ поиска заказа предусмотрен на экране выдачи помимо QR клиента?","options":["Последние четыре цифры номера телефона","Номер возвратной коробки TRBX","Номер полки","Код рулона стикеров"],"answer":0,"explanation":"На экране выдачи можно использовать предусмотренный поиск по последним четырём цифрам телефона."}],"role":"Сотрудник","version":"","when":"Проверка клиента, товара и завершение операции.","check":"Сверьте выданные товары и оформленные отказы с итоговыми статусами в программе. Не выдавайте товар, который не найден физически."},{"id":"l11","cat":"Выдача клиенту","title":"Примерка и отказ","summary":"Как корректно снять товар с выдачи.","steps":["Проверьте, какие позиции клиент берёт на примерку.","После примерки уточните решение по каждому товару.","Для отказа используйте предусмотренную функцию снятия с выдачи.","При наличии брака или повреждения зафиксируйте соответствующую отметку.","Подготовьте отказанный товар к возврату по инструкции."],"notes":"Не путайте обычный отказ и товар, который система запрещает возвращать без специальных оснований.","quiz":[{"q":"После примерки покупатель не берёт товар. Как оформить?","options":["Зафиксировать отказ в предусмотренном процессе","Пометить товар как выданный","Оставить заказ в статусе выданного без товара","Оформить его как DBS"],"answer":0,"explanation":"Зафиксировать отказ в предусмотренном процессе. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как корректно снять товар с выдачи.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l12","cat":"Выдача клиенту","title":"Неотказные и невозвратные товары","summary":"Разница между запретом отказа и домашним возвратом.","steps":["До завершения выдачи проверьте специальные ограничения в карточке товара.","Объясните клиенту правила, которые отображает система.","Если клиент заявляет о дефекте, действуйте по процедуре проверки брака и обращения клиента.","Не обещайте возврат или отказ, если система не разрешает его оформить."],"notes":"У разных категорий товаров правила различаются; решения принимайте по текущему статусу товара.","quiz":[{"q":"Покупатель спрашивает об ограничениях возврата товара. На что опираться?","options":["На категорию товара и действующие правила в программе","На личное мнение сотрудника","На стоимость упаковки","На размер ячейки хранения"],"answer":0,"explanation":"На категорию товара и действующие правила в программе. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Разница между запретом отказа и домашним возвратом.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l13","cat":"Выдача клиенту","title":"Отмена заказа во время выдачи","summary":"Что делать со статусом «Ожидает отмены».","steps":["Проверьте системный статус заказа.","Если отображается «Ожидает отмены» или «Нельзя выдать», не выдавайте товар.","Не добавляйте его в возвратную коробку до решения системы.","После изменения статуса действуйте по доступной операции: возврат или размещение в ячейке."],"notes":"В десктопе статус виден в возвратах; в мобильном приложении — «Вернуть» → «Ждут отмены».","quiz":[{"q":"Клиент отменяет товар при выдаче. Какой принцип важен?","options":["Оформить отмену в программе до завершения операции","Сначала отметить товар выданным","Передать товар клиенту без отметки","Закрыть возвратную коробку вместо отмены"],"answer":0,"explanation":"Оформить отмену в программе до завершения операции. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Что делать со статусом «Ожидает отмены».","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l14","cat":"Выдача клиенту","title":"Выдать товар из отказа","summary":"Сценарий, когда клиент передумал.","steps":["Проверьте, что с момента отказа прошло не более 24 часов.","Убедитесь, что товар ещё не помещён в закрытую возвратную коробку.","В десктопной программе используйте функцию «Выдать из отмены», если она доступна.","Проверьте статус и завершите выдачу штатным способом."],"notes":"Если система не предлагает операцию, не обходите ограничение вручную.","quiz":[{"q":"Товар ранее был отменён, но требуется предусмотренная выдача из отмены. Где искать функцию?","options":["В разделе выдачи «Выдать из отмены»","В «Возврат» → «Картон»","В разделе WB Track → «Коробки»","В настройках голосовой озвучки"],"answer":0,"explanation":"В разделе выдачи «Выдать из отмены». Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Сценарий, когда клиент передумал.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l15","cat":"Выдача клиенту","title":"Проблема с оплатой","summary":"Оплата не проходит или клиент ушёл с товаром.","steps":["Проверьте статус оплаты в программе; не считайте заказ оплаченным по словам клиента.","Если оплата не проходит повторно или клиент ушёл без оплаты, оформите предусмотренный тикет.","Подготовьте записи с камер, показывающие ситуацию.","Передайте ссылку на видео в установленный срок."],"notes":"В инструкции WB Point от 03.10.2025 для тикета «Проблема с оплатой» указан срок предоставления доказательств 24 часа.","quiz":[{"q":"На экране выдачи заказ отмечен как неоплаченный. Что важно?","options":["Проверить статус оплаты до завершения выдачи","Считать все товары оплаченными","Изменить статус вручную без основания","Закрыть карточку без проверки"],"answer":0,"explanation":"Проверить статус оплаты до завершения выдачи. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Оплата не проходит или клиент ушёл с товаром.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l16","cat":"Выдача клиенту","title":"Подарочные сертификаты","summary":"Приёмка и выдача особой категории.","steps":["Примите сертификаты по предусмотренной схеме.","При выдаче отсканируйте соответствующие коды и идентификатор клиента.","Проверьте особый порядок выдачи в десктопной или мобильной программе.","Не обещайте обналичивание, отказ или возврат вне правил системы."],"notes":"","quiz":[{"q":"Покупатель пришёл с подарочным сертификатом. Где искать работу с ним?","options":["В разделе выдачи с функциями сертификатов","В меню возврата картона","В разделе DBS-поставок","В WB Track → «Коробки»"],"answer":0,"explanation":"В разделе выдачи с функциями сертификатов. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Приёмка и выдача особой категории.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l17","cat":"Возвраты","title":"Возврат товара из дома","summary":"Как принять клиентский возврат.","steps":["Попросите QR возврата из клиентского приложения.","Определите тип QR: общий для заказов или конкретного товара.","При общем QR дополнительно отсканируйте ШК возвращаемого товара.","При предметном QR сравните товар с карточкой и заявкой клиента.","Проверьте состояние, комплектность, маркировку и возможное одобрение заявки по браку.","Подтвердите приём только при соответствии правилам.","Откройте «Возврат» → «Товары» и найдите нужную позицию в соответствующем процессе.","Проверьте упаковку, комплектность и состояние возвращаемого товара до завершения операции; при обнаружении признаков брака действуйте по предусмотренной процедуре."],"notes":"В десктопе: «Возврат» → «Товары» → «Возврат от клиента»; в мобильном: «Вернуть» → «Принять возврат от клиента».","quiz":[{"q":"Клиент принёс товар по оформленному возврату из дома. Что делать сначала?","options":["Найти нужный возврат в предусмотренном разделе и проверить товар","Положить товар в первую коробку без оформления","Выдать товар следующему клиенту","Сменить ПВЗ в настройках"],"answer":0,"explanation":"Найти нужный возврат в предусмотренном разделе и проверить товар. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Клиент хочет оформить возврат из дома. Что важно проверить в первую очередь?","options":["Что возврат относится к нужному заказу и доступен в системе","Что товар подходит по цвету к полке","Что есть пустая коробка WB MP","Что клиент помнит номер ячейки"],"answer":0,"explanation":"Сначала необходимо установить корректный сценарий возврата и идентифицировать товар."},{"q":"Товар с явным повреждением поступил на возврат. Как поступить?","options":["Не отмечать дефект, если упаковка есть","Проверить товар и оформить обнаруженный дефект по правилам программы","Положить в любую открытую коробку","Оформить как новый товар"],"answer":1,"explanation":"Повреждение требует предусмотренной процедуры проверки и отметки брака, а не сокрытия дефекта."}],"role":"Сотрудник","version":"","when":"Как принять клиентский возврат.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l18","cat":"Возвраты","title":"Возврат без штрихкода","summary":"Что делать, если на товаре нет ШК.","steps":["Откройте предусмотренную в десктопе функцию «На товаре нет ШК».","Найдите подходящую позицию среди доступных недавних заказов или одобренных заявок.","Сравните характеристики товара с карточкой и заявкой.","Следуйте подсказкам системы для оформления и маркировки."],"notes":"В инструкции 2025 года описано написание ШК на бумаге; этот шаг требует сверки с актуальным интерфейсом.","quiz":[{"q":"На возвращаемом товаре отсутствует читаемый штрихкод. Как поступить?","options":["Использовать предусмотренный процесс идентификации и возврата","Придумать произвольный ШК","Оформить возврат на другой товар","Отправить без маркировки"],"answer":0,"explanation":"Использовать предусмотренный процесс идентификации и возврата. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Что делать, если на товаре нет ШК.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l19","cat":"Возвраты","title":"Возвратная коробка","summary":"Как сформировать и передать коробку на склад.","steps":["Откройте вкладку «Возврат» → «Коробки». Это отдельный раздел обычных возвратных коробок; коробки WB MP и WB Track оформляются по другим правилам.","Выберите тип коробки в зависимости от товара: обычный возврат, брак или товары маркетплейсов, если такие варианты доступны в интерфейсе.","Создайте или откройте нужную коробку и проверьте её TRBX — идентификатор, по которому коробку учитывают при отгрузке.","Перед добавлением товара убедитесь, что он оформлен на возврат и упакован согласно его состоянию. Сканируйте товар, затем проверяйте, что он появился в составе нужной коробки.","Проверяйте количество товаров и статус коробки. Не помещайте товары в уже закрытую коробку и не смешивайте несовместимые потоки.","Закройте коробку в программе по действующим правилам и подготовьте к передаче водителю. Фактическую передачу сверяйте с отгрузкой.","Откройте «Возврат» → «Коробки». Проверьте тип коробки: обычная, для брака или для МП-товаров — это разные потоки.","Перед помещением товара убедитесь, что сканируется нужный TRBX и коробка остаётся открытой.","Перед закрытием сопоставьте фактическое содержимое с тем, что показано в программе. Не смешивайте разные типы возвратов."],"notes":"Коробки для обычных возвратов, WB MP и WB Track относятся к разным процессам. Не переносите правила и TRBX между ними без соответствующего сценария программы.","quiz":[{"q":"Готовите возвратную коробку для брака. Что проверить?","options":["Правильный тип коробки и соответствие TRBX","Только цвет стен ПВЗ","Наличие QR клиента для выдачи","ПИН-код другого сотрудника"],"answer":0,"explanation":"Правильный тип коробки и соответствие TRBX. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Сотрудник готовит обычную возвратную коробку. Куда перейти?","options":["«Возврат» → «Коробки»","«Возврат» → «WB MP»","«Доставки» → «Коробки»"],"answer":0,"explanation":"Обычные возвраты оформляются в «Возврат» → «Коробки», отдельно от WB MP и Track."},{"q":"В закрытую возвратную коробку нужно добавить ещё один товар. Что делать?","options":["Положить товар внутрь без сканирования","Открыть другую подходящую коробку и оформить товар","Исправить количество от руки на коробке"],"answer":1,"explanation":"Закрытая коробка не предназначена для дальнейшего добавления товаров."},{"q":"В какой части WB ПВЗ работают с обычными возвратными коробками?","options":["«Возврат» → «Коробки»","«Выдача» → «Сертификаты»","«Доставки» → «Новый клиент»","«Приёмка» → «DBS»"],"answer":0,"explanation":"Обычные возвратные коробки находятся в разделе «Возврат» → «Коробки»."},{"q":"Можно ли считать коробку WB Track той же коробкой, что и обычный возврат TRBX?","options":["Да, если обе открыты","Нет: у WB Track отдельный процесс и учёт коробок","Да, если коробки одинакового размера","Да, если товары находятся в одном ПВЗ"],"answer":1,"explanation":"WB Track и обычные возвраты — разные логистические процессы с отдельными экранами."}],"role":"Сотрудник","version":"","when":"Как сформировать и передать коробку на склад.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l20","cat":"Возвраты","title":"Правильная маркировка TRBX","summary":"Как избежать ошибки сканирования коробки.","steps":["Оставьте на коробке только актуальную читаемую этикетку TRBX.","Удалите или закройте старые читаемые штрихкоды.","Не заклеивайте термоэтикетку скотчем поверх печати.","Если этикетка утрачена, восстановите QR по идентификатору TRBX и номеру предусмотренным способом."],"notes":"Пример структуры: TRBX + номер коробки. Не подставляйте выдуманный номер.","quiz":[{"q":"Водитель забирает возвратную коробку. Какой код должен соответствовать ей?","options":["TRBX именно этой коробки","Код клиента для выдачи","ПИН-код менеджера","QR для регистрации сотрудника"],"answer":0,"explanation":"TRBX именно этой коробки. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как избежать ошибки сканирования коробки.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l21","cat":"Возвраты","title":"Переупаковка товара","summary":"Подготовка отказа к отправке на склад.","steps":["Сверьте товар с карточкой: артикул, размер, цвет, бренд, комплектность и состояние.","Используйте подходящий пакет и зарегистрированный стикер, назначенный программой.","Сохраните обязательную маркировку, включая «Честный знак».","Уберите лишние читаемые коды, не относящиеся к текущему товару.","Поместите товар в коробку и закройте упаковку в правильной последовательности."],"notes":"Для КГТ может использоваться сценарий «Без упаковки». Не переупаковывайте повреждённые и неподходящие товары как исправные.","quiz":[{"q":"У возвращаемого товара повреждена упаковка. Что важно?","options":["Переупаковать по правилам и сохранить читаемую маркировку","Оставить товар без защиты","Наклеить новый код на другой товар","Отправить товар вместе с мусором"],"answer":0,"explanation":"Переупаковать по правилам и сохранить читаемую маркировку. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Подготовка отказа к отправке на склад.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l22","cat":"Возвраты","title":"Регистрация рулонов стикеров","summary":"Как активировать наклейки для переупаковки.","steps":["Откройте меню WB ПВЗ → «Наклейки для работы с товаром». В этом разделе можно напечатать наклейки для ячеек и работать с рулонами возвратных стикеров.","Для печати наклеек ячеек задайте нужный диапазон. За одну операцию можно подготовить до 1000 наклеек, если это предусмотрено текущим интерфейсом.","Для регистрации рулона возвратных стикеров найдите соответствующий мастер и выполняйте этапы в указанном порядке.","При указании первого стикера ориентируйтесь на наименьший числовой номер в рулоне, а не на случайную наклейку из середины.","После регистрации убедитесь, что рулон привязан к вашему ПВЗ. При ошибке сканирования следуйте подсказкам мастера и не отмечайте регистрацию завершённой вручную.","В меню программы найдите «Наклейки для работы с товаром» и выберите регистрацию рулона возвратных стикеров.","Регистрация проходит по этапам, указанным программой. Для нового рулона начинайте с первой наклейки с наименьшим числовым значением.","При частично использованном рулоне следуйте инструкции программы для оставшихся наклеек; не указывайте уже израсходованные номера."],"notes":"Рулон, зарегистрированный на другом ПВЗ, может быть отклонён. Используйте только зарегистрированные наклейки.","quiz":[{"q":"Регистрируете новый рулон возвратных стикеров. С какой наклейки начать?","options":["С первой с наименьшим числовым значением","С произвольной из середины рулона","С наклейки другой точки выдачи","С последней наклейки другого рулона"],"answer":0,"explanation":"С первой с наименьшим числовым значением. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как активировать наклейки для переупаковки.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l23","cat":"Возвраты","title":"Возврат картона","summary":"Что делать с пустыми коробками.","steps":["Соберите подлежащий возврату картон и удалите старые наклейки.","Укажите количество и оформите возврат картона через рабочую программу.","Передайте подготовленный картон водителю.","Если водитель не забирает возврат, оформите логистическое обращение с подтверждением.","Вкладка «Возврат» содержит отдельный раздел «Картон». Он не является коробкой для возврата товаров.","Оформляйте возврат картона только через соответствующий процесс; не помещайте в него клиентские товары и WB MP."],"notes":"В обучающих материалах указаны исключения для авиа- и железнодорожной логистики. После создания возврата количество картона может быть недоступно для изменения.","quiz":[{"q":"Что оформляют через «Возврат» → «Картон»?","options":["Возврат картона как отдельный процесс","Приёмку WB MP от продавца","Выдачу клиентского заказа","Регистрацию ПИН-кода"],"answer":0,"explanation":"Возврат картона как отдельный процесс. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Что делать с пустыми коробками.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l24","cat":"Возвраты","title":"Утилизация товаров","summary":"Как списывать товары, назначенные в утиль.","steps":["Откройте в десктопном WB ПВЗ «Возврат» → «Утиль».","Выберите или отсканируйте позиции, доступные для утилизации.","Нажмите «Утилизировать» и подтвердите операцию.","Удалите брендинг и маркировку Wildberries перед физической утилизацией."],"notes":"Нельзя самостоятельно отправлять в утиль товары, которых нет в соответствующем списке.","quiz":[{"q":"Товар назначен на утилизацию. Что важно?","options":["Следовать указанному в программе процессу утилизации","Оформить его как обычную выдачу","Передать клиенту без статуса","Положить в любую коробку WB Track"],"answer":0,"explanation":"Следовать указанному в программе процессу утилизации. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как списывать товары, назначенные в утиль.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l25","cat":"Брак и безопасность","title":"Проверка товара на брак","summary":"Как отличить дефект от допустимой особенности.","steps":["Осмотрите товар и упаковку под камерой.","Проверьте комплектность, швы, фурнитуру, поверхности, запахи и загрязнения.","Отличайте устранимую грязь на внешней упаковке от повреждения самого товара.","При выявленном дефекте выберите корректный тип брака и степень повреждения.","Сделайте необходимые фото и комментарий, если программа их запрашивает."],"notes":"Для подтверждения брака в присланных памятках указаны четыре фото: спереди, сзади, ШК и крупный план дефекта.","quiz":[{"q":"На товаре обнаружены признаки повреждения. Что делать?","options":["Проверить основания для брака и оформить отметку по процедуре","Игнорировать повреждение","Автоматически признать любую вещь подменой","Сразу удалить товар из учёта"],"answer":0,"explanation":"Проверить основания для брака и оформить отметку по процедуре. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как отличить дефект от допустимой особенности.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l26","cat":"Брак и безопасность","title":"Подмена товара","summary":"Порядок действий при подозрении на подмену.","steps":["Зафиксируйте фактический товар и его признаки под камерой.","Не смешивайте его с другими товарами и не скрывайте расхождение.","Отметьте проблему штатным способом в программе.","Сохраните видео приёмки, выдачи, отказа, упаковки и передачи возврата.","При удержании используйте соответствующее оспаривание в WB Point."],"notes":"Для оспаривания удержания за подмену в инструкции 2025 года указан срок 7 дней и только одна возможность по конкретному ШК.","quiz":[{"q":"Марка на товаре не совпала с карточкой. Это автоматически подмена?","options":["Нет, нужно проверить карточку, брендирование и другие признаки","Да, любой другой логотип означает подмену","Да, если товар недорогой","Да, если клиент просит возврат"],"answer":0,"explanation":"Нет, нужно проверить карточку, брендирование и другие признаки. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Порядок действий при подозрении на подмену.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l27","cat":"Брак и безопасность","title":"Зависшие ШК","summary":"Пошаговая диагностика товара без движения в системе.","steps":["Проверьте, был ли товар фактически принят в ПВЗ.","Поищите товар на полках, в соседних ячейках и возвратных коробках.","Если товар найден, проверьте его статус и назначение: возврат, утиль, поставщик.","Если он не принят — выполните приёмку, если операция доступна; затем оформите возврат.","Если товар отправлен в другой коробке, оформите тикет с номером коробки и доказательствами.","При удержании за непоступивший товар соберите непрерывные записи и оспорьте в срок."],"notes":"Оспаривание — в течение 7 дней; ответ на запрос поддержки — в течение 48 часов. Видео с камер хранить минимум 90 дней в РФ.","quiz":[{"q":"ШК числится зависшим. Что делать?","options":["Проверить историю статусов и фактическое движение товара","Повторно принять любой другой ШК","Закрыть все возвратные коробки","Удалить историю из программы"],"answer":0,"explanation":"Проверить историю статусов и фактическое движение товара. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Пошаговая диагностика товара без движения в системе.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l28","cat":"Брак и безопасность","title":"Пожарная безопасность","summary":"Основные запреты и действия по предотвращению риска.","steps":["Не загромождайте выходы и пути эвакуации.","Следите за исправностью розеток и электроприборов.","Не храните горючие материалы у источников нагрева.","Не допускайте курения и использования открытого огня в помещении.","Контролируйте наличие и состояние огнетушителей согласно регламенту."],"notes":"При признаках пожара прежде всего обеспечьте безопасность людей и вызовите экстренные службы.","quiz":[{"q":"Проход к эвакуационному выходу заставлен коробками. Что делать?","options":["Немедленно освободить проход","Оставить до конца смены","Скрыть коробки за шторой","Оформить коробки как возврат"],"answer":0,"explanation":"Немедленно освободить проход. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Основные запреты и действия по предотвращению риска.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l29","cat":"Курьерские заказы","title":"Подготовка курьерского заказа","summary":"Сборка заказа на доставку клиенту.","steps":["Откройте список курьерских заказов в WB ПВЗ.","Найдите позиции со статусом «Ожидает сборки».","Просканируйте товары и подтвердите их наличие.","Отметьте повреждённый ШК, ненайденный или повреждённый товар через штатные функции.","Подготовьте заказ к передаче курьеру под камерой."],"notes":"При позднем обнаружении товара до прихода курьера используйте предусмотренный сценарий восстановления.","quiz":[{"q":"Курьерский заказ собирают к передаче. Что проверить?","options":["Состав заказа и соответствие операции в программе","Только внешний вид рюкзака","Наличие свободного TRBX для WB MP","Настройку ПИН-кода"],"answer":0,"explanation":"Состав заказа и соответствие операции в программе. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Сборка заказа на доставку клиенту.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l30","cat":"Курьерские заказы","title":"Выдача заказа курьеру","summary":"Проверка курьера и передача подготовленного заказа.","steps":["Попросите курьерский QR-код из «WB Курьер».","Откройте выдачу курьеру и просканируйте QR.","Проверьте подготовленные и неподготовленные позиции.","Подтвердите фактически переданные товары; при необходимости оформите частичную выдачу.","Выдайте предусмотренное системой количество пакетов."],"notes":"Курьер не должен вскрывать упаковку товаров. Для отдельных служб может применяться дополнительный код.","quiz":[{"q":"Курьер прибыл за собранным заказом. Как подтвердить передачу?","options":["Выполнить предусмотренную выдачу курьеру в программе","Отдать пакет без фиксации","Оформить его как возврат из дома","Зарегистрировать рулон стикеров"],"answer":0,"explanation":"Выполнить предусмотренную выдачу курьеру в программе. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Проверка курьера и передача подготовленного заказа.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l31","cat":"Курьерские заказы","title":"Возврат заказа от курьера","summary":"Приём заказа, который не доставили клиенту.","steps":["Откройте приём возврата курьера в программе.","Просканируйте курьерский QR и фактически возвращённые товары.","Осмотрите вскрытые или повреждённые товары.","Отметьте отсутствующие позиции — не подтверждайте их как полученные.","Направьте принятый товар «На полку» или «В отказ» по статусу."],"notes":"Возврат курьерской доставки должен оформляться в том же ПВЗ, из которого заказ выдавался.","quiz":[{"q":"Курьер возвращает заказ. Что важно?","options":["Оформить фактический возврат через соответствующий процесс","Пометить его доставленным клиенту","Смешать с неучтённой поставкой","Выдать следующему клиенту"],"answer":0,"explanation":"Оформить фактический возврат через соответствующий процесс. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Приём заказа, который не доставили клиенту.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l32","cat":"Курьерские заказы","title":"Разбор курьерского заказа","summary":"Если заказ отменён до передачи курьеру.","steps":["Найдите заказ со статусом «Ожидает разборки».","Просканируйте позиции в процессе разбора.","Верните товары в предусмотренные ячейки.","Закончите разбор до окончания смены."],"notes":"","quiz":[{"q":"При разборе курьерского заказа есть расхождение. Что делать?","options":["Сверить состав и статусы до завершения разбора","Считать любой пакет полным","Сразу закрыть все коробки","Поменять ПИН-код сотрудника"],"answer":0,"explanation":"Сверить состав и статусы до завершения разбора. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Если заказ отменён до передачи курьеру.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l33","cat":"Спецсервисы","title":"WB Track — приём посылки","summary":"Отправка клиентской посылки через ПВЗ.","steps":["Попросите клиента оформить отправление и показать QR в приложении.","Под камерой проверьте содержимое и отсутствие запрещённых предметов.","Проверьте упаковку и соответствие ограничениям по весу.","После подтверждения оплаты оформите посылку и поместите в отдельный сейф-пакет.","На каждый пакет наклейте собственный штрихкод отправления.","Сформируйте отдельную возвратную коробку для отправлений и передайте водителю.","В верхнем меню откройте «Доставки», затем WB Track → «Доставки».","Для нового отправления выберите «Новый клиент» и отсканируйте QR-код из приложения Wildberries клиента.","Сверьте отображаемую операцию с фактической посылкой. Не путайте WB Track с обычной выдачей и возвратными коробками WB ПВЗ."],"notes":"В присланных материалах: до 25 кг на посылку; не более 60 отправлений в коробке; один сейф-пакет — одна посылка.","quiz":[{"q":"Клиент хочет отправить посылку через WB Track. С чего начать в программе?","options":["«Доставки» → WB Track → «Новый клиент»","«Возврат» → «Картон»","«Выдача» → «Выдать из отмены»","«Ещё» → «Смена ПВЗ»"],"answer":0,"explanation":"«Доставки» → WB Track → «Новый клиент». Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Отправка клиентской посылки через ПВЗ.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l34","cat":"Спецсервисы","title":"WB Track — запрещённые вложения","summary":"Что нельзя принимать к отправке.","steps":["Откажите в приёме опасных, взрывоопасных и легковоспламеняющихся предметов.","Не принимайте оружие, наркотики, алкоголь и никотиновую продукцию.","Не принимайте наличные, документы личности, животных и растения.","Не принимайте скоропортящиеся продукты, жидкости и иные запрещённые категории.","Если клиент отказывается показать содержимое, не принимайте отправление."],"notes":"Полный актуальный перечень ограничений необходимо сверять с действующими правилами.","quiz":[{"q":"Клиент принёс запрещённое к отправке вложение. Что делать?","options":["Не принимать отправление, руководствуясь ограничениями WB Track","Принять без оформления","Замаскировать описание вложения","Поместить в коробку для брака"],"answer":0,"explanation":"Не принимать отправление, руководствуясь ограничениями WB Track. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Что нельзя принимать к отправке.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l35","cat":"Спецсервисы","title":"WB Ресейл — приём от продавца","summary":"Продажа вещей между клиентами WB.","steps":["Проверьте присутствие продавца и его QR.","Осмотрите товар и упаковку под камерой.","Определите способ отправки: WB Track либо WB МП.","Для WB Track оформите ресейл в разделе посылок и используйте предусмотренный код отправления.","Для WB МП проверьте наличие ШК товара и коробки WB МП.","Передайте товар в соответствующую коробку для вывоза.","Для работы с WB Track используйте отдельные вкладки «Доставки» и «Коробки».","В разделе коробок доступен поиск по TRBX, фильтры по статусу и датам открытия/закрытия, а также просмотр состава коробки."],"notes":"В присланных инструкциях для товара ресейл: до 5 кг, максимальная сторона 60 см, сумма сторон до 140 см. При WB Track дополнительный сейф-пакет поверх упаковки продавца не нужен.","quiz":[{"q":"Нужно посмотреть содержимое коробки WB Track. Где это сделать?","options":["В WB Track → «Коробки» по её TRBX","В «Возврат» → «Картон»","В «Выдача» → «Подарочные сертификаты»","В настройках звука"],"answer":0,"explanation":"В WB Track → «Коробки» по её TRBX. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Продажа вещей между клиентами WB.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l36","cat":"Спецсервисы","title":"WB Ресейл — выдача и возврат","summary":"Особенности заказа вторичной продажи.","steps":["При выдаче покупателю проверьте статус заказа и доступность отказа.","При отказе оформите возврат в программе.","Возвращённый продавцу товар выдавайте по специальному статусу.","Не оформляйте возврат ресейла из дома, если система не поддерживает такую операцию."],"notes":"В присланных материалах: хранение у покупателя 12 дней, возврат продавцу — 7 дней до утилизации. Проверяйте актуальность сроков.","quiz":[{"q":"Поступила операция WB Ресейл. Как действовать?","options":["Использовать предусмотренный процесс WB Track / Ресейл","Оформить как обычную коробку WB MP","Положить товар в картон без учёта","Выдать товар по чужому QR"],"answer":0,"explanation":"Использовать предусмотренный процесс WB Track / Ресейл. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Особенности заказа вторичной продажи.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l37","cat":"Спецсервисы","title":"Товары поставщика","summary":"Приём и выдача товаров, возвращённых поставщику.","steps":["Примите товары поставщика через «Приёмка» и разместите в ячейке.","При выдаче отсканируйте QR поставщика из его личного кабинета.","Проверьте список и фактическое количество товаров.","При необходимости оформите отказ поставщика от отдельных позиций штатной функцией."],"notes":"Не путайте этот сценарий с выдачей товаров партнёрских маркетплейсов.","quiz":[{"q":"Продавец передаёт товар по отдельной схеме поставки. Что важно?","options":["Выбрать соответствующий тип поставки и проверить маркировку","Оформить как клиентский отказ","Принимать любые товары без учёта","Заменить ШК на произвольный"],"answer":0,"explanation":"Выбрать соответствующий тип поставки и проверить маркировку. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Приём и выдача товаров, возвращённых поставщику.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l38","cat":"Спецсервисы","title":"Партнёрские маркетплейсы","summary":"Особый порядок выдачи сторонних товаров.","steps":["Примите поставку по предусмотренным QR и ШК.","При выдаче проверьте отметку партнёрского товара в программе.","Сканируйте товары и используйте предусмотренный код клиента.","Не оформляйте обычный отказ или возврат в ПВЗ, если это запрещено правилами партнёра."],"notes":"Порядок отличается от стандартной выдачи Wildberries и от товаров поставщика.","quiz":[{"q":"Поступила операция другого маркетплейса. Что делать?","options":["Использовать предусмотренный отдельный рабочий процесс","Оформить её как обычную выдачу WB","Положить в WB MP без проверки","Присвоить чужой TRBX"],"answer":0,"explanation":"Использовать предусмотренный отдельный рабочий процесс. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Особый порядок выдачи сторонних товаров.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l39","cat":"Поддержка и штрафы","title":"Как создать тикет WB Point","summary":"Общий алгоритм обращения в поддержку.","steps":["Откройте WB Point → «Тикеты».","Выберите подходящую тему, ПВЗ и причину обращения.","Опишите факты: что произошло, когда, какие ШК или коробки затронуты.","Приложите нужные фото, видео и работающие ссылки.","Отправьте обращение и отслеживайте запросы специалиста."],"notes":"По инструкции 03.10.2025 ответ на запрос поддержки обычно нужен в течение 48 часов; для проблемы с оплатой — 24 часа.","quiz":[{"q":"Нужно сообщить в поддержку о расхождении. Какой тикет полезнее?","options":["С конкретными ШК, временем, описанием и доказательствами","Без адреса и без описания","С одним словом «помогите»","С чужими данными входа"],"answer":0,"explanation":"С конкретными ШК, временем, описанием и доказательствами. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Общий алгоритм обращения в поддержку.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l40","cat":"Поддержка и штрафы","title":"Оспаривание брака и подмены","summary":"Как подготовить доказательства.","steps":["Найдите удержание в соответствующем разделе WB Point.","Проверьте доступность кнопки «Оспорить».","Подготовьте видео приёмки, работы с клиентом, возврата в коробку и передачи водителю.","Укажите в комментарии, что видно на каждом фрагменте.","Отправьте обращение и отвечайте на запросы поддержки вовремя."],"notes":"В документах 2025 года указан срок 7 дней и однократность оспаривания по конкретному товару.","quiz":[{"q":"Оспариваете удержание за подмену. Что приложить?","options":["Сведения о товаре, статусах и относящееся к случаю видео","Только просьбу отменить штраф","Пароль сотрудника","Фото другого товара"],"answer":0,"explanation":"Сведения о товаре, статусах и относящееся к случаю видео. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как подготовить доказательства.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l41","cat":"Поддержка и штрафы","title":"Оспаривание оценки клиента","summary":"Как оспорить необоснованный отзыв.","steps":["Откройте рейтинг ПВЗ в WB Point.","Найдите оценку 1 или 2 звезды с доступной кнопкой оспаривания.","Нажмите «Оспорить»; тикет создаётся автоматически.","Проверьте, что запись работы с клиентом доступна в видеоархиве.","Дождитесь решения и уведомления."],"notes":"В инструкции 2025 года — 48 часов с появления оценки, один раз. Некоторые отзывы с пониженным весом оспаривать нельзя.","quiz":[{"q":"Клиент поставил спорную оценку. Что важно?","options":["Соблюсти срок и представить фактические основания оспаривания","Удалить оценку из приложения самостоятельно","Поменять рейтинг вручную","Оспорить без проверки причины"],"answer":0,"explanation":"Соблюсти срок и представить фактические основания оспаривания. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как оспорить необоснованный отзыв.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l42","cat":"Поддержка и штрафы","title":"Логистика и водитель","summary":"Жалобы, несвоевременная доставка и невывоз коробок.","steps":["В WB Point откройте «Тикеты» → «Вопросы по логистике».","Выберите причину: жалоба на водителя, удержание за приёмку, доставка, невывоз возвратов/картона, лимиты.","Укажите дату, время, номер коробки и фактическую ситуацию.","Приложите непрерывную запись с камер, подтверждающую проблему.","Следите за ответом и своевременно предоставляйте дополнения."],"notes":"Для жалобы на водителя видеоподтверждение обязательно по инструкции от 03.10.2025.","quiz":[{"q":"Водитель отметил поставку до её фактической передачи. Что делать?","options":["Зафиксировать расхождение и обратиться через предусмотренную поддержку","Подтвердить всё как принятое","Отдать другие товары вместо поставки","Сменить ПВЗ в программе"],"answer":0,"explanation":"Зафиксировать расхождение и обратиться через предусмотренную поддержку. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Жалобы, несвоевременная доставка и невывоз коробок.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l43","cat":"Поддержка и штрафы","title":"Помощник WB ПВЗ","summary":"Как обратиться в чат и оценить ответ.","steps":["В десктопном WB ПВЗ нажмите значок сообщения справа вверху.","В мобильном WB ПВЗ откройте «Ещё» → «Помощник».","Опишите проблему и приложите необходимые данные.","После закрытия обращения оцените качество ответа в появившемся окне."],"notes":"Окно оценки появляется в течение двух часов после закрытия обращения.","quiz":[{"q":"«Помощник WB ПВЗ» дал совет, не совпадающий с экраном программы. Что делать?","options":["Проверить актуальный процесс и при необходимости обратиться в поддержку","Слепо повторить действие","Изменить чужие статусы","Передать свой ПИН-код"],"answer":0,"explanation":"Проверить актуальный процесс и при необходимости обратиться в поддержку. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как обратиться в чат и оценить ответ.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l44","cat":"Поддержка и штрафы","title":"Видеодоказательства","summary":"Чек-лист перед оспариванием удержания.","steps":["Убедитесь, что на видео полностью видны товар, коробка и действия сотрудника.","Проверьте, что обзор не перекрыт человеком, стеллажом или другими предметами.","Используйте непрерывные записи с камер ПВЗ без склеек.","Проверьте даты, время, ссылки и доступ для просмотра.","Сохраните архив на необходимый срок."],"notes":"В инструкциях для РФ — не менее 90 дней, для Беларуси — 30 дней. Видео с телефона для таких оспариваний не принимаются.","quiz":[{"q":"Нужно оспорить ситуацию с товаром. Какое видео полезно?","options":["Запись именно спорной операции с нужным временем и товаром","Любая запись другой смены","Видео без нужного события","Случайное видео из интернета"],"answer":0,"explanation":"Запись именно спорной операции с нужным временем и товаром. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Чек-лист перед оспариванием удержания.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l45","cat":"Поддержка и штрафы","title":"Какие тикеты бывают","summary":"Краткий навигатор по темам WB Point.","steps":["Удержания: «Зависшие ШК», «Подмены», «Брак».","Клиенты: «Недобросовестный клиент», «Оспаривание оценок», «Проблема с оплатой».","Техника: «Электронные замки», «Техподдержка десктопа».","ПВЗ: «Ремонт», «Аудит», «Низкий рейтинг», «График работы», «Смена собственника», «Субсидии».","Логистика: водитель, приёмка, доставка, возвратные коробки, лимиты."],"notes":"Часть тикетов доступна только собственнику. Список тем может изменяться.","quiz":[{"q":"Для какой ситуации нужен тикет о поставке?","options":["Поставка отмечена водителем, но физически не передана","Покупатель спрашивает про примерочную","Сотрудник забыл ПИН-код","Нужно открыть карточку товара"],"answer":0,"explanation":"Поставка отмечена водителем, но физически не передана. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Собственник / менеджер","version":"","when":"Краткий навигатор по темам WB Point.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"l46","cat":"Поддержка и штрафы","title":"Тикеты собственника","summary":"Операционные вопросы, доступные владельцу.","steps":["Для изменения графика выберите «График работы» и укажите причину с подтверждениями.","Для подключения приёмки МП выберите «Приёмка МП».","Для ремонта, аудита, субсидии или смены собственника используйте одноимённую тему.","Для подозрения на кражу сотрудником выберите «Чёрный список» и приложите запись и ШК.","Для проблем с работой ПВЗ выберите техническую тему и опишите воспроизводимые шаги."],"notes":"Для «Субсидий» в инструкции 2025 года указан мораторий 30 дней на повторное обращение.","quiz":[{"q":"Собственник запрашивает изменение режима ПВЗ. Что важно указать?","options":["Новый режим и причину изменения","Только слово «срочно»","ШК случайного товара","Код курьера"],"answer":0,"explanation":"Новый режим и причину изменения. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Собственник","version":"","when":"Операционные вопросы, доступные владельцу.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n1","cat":"Потерянные товары","title":"Потерялся товар при выдаче","summary":"Статус «Утерян на ПВЗ» и 48 часов на поиск.","steps":["Во вкладке «Выдача» откройте заказ клиента и проверьте назначенную ячейку. Осмотрите её и соседние места, не передавая клиенту другой товар.","Если товар не найден, используйте «Не могу найти» в разделе «Проверка товаров», когда функция доступна вашему ПВЗ. Программа может присвоить статус «Утерян на ПВЗ».","После такой отметки у пункта обычно есть 48 часов на поиск. Для заказов с последним днём хранения предусмотрено продление на два дня в рамках описанного процесса.","Проверьте вкладку «Возврат» → «Товары» → «Надо найти» и организуйте повторный поиск по ШК, истории ячеек и складу.","Если товар найден, повторно отсканируйте его через «Приёмка»/«Принять» в предусмотренном сценарии, чтобы восстановить учёт. Клиенту должно прийти уведомление.","Если не нашли за 48 часов, по описанному порядку заказ отменяется, а стоимость может быть удержана с ПВЗ. Учитывайте, что функция внедрялась поэтапно: проверяйте доступность в вашей версии.","Если при выдаче товар не найден, используйте предусмотренное действие «Не могу найти» в проверке товаров. При доступности функции система присвоит статус «Утерян на ПВЗ».","Для пилотного процесса указан срок 48 часов на поиск. Если товар найден, повторно отсканируйте его через «Приёмка» → «Принять» и проверьте обновление статуса.","В разделе возвратов можно использовать фильтр «Надо найти» для контроля таких позиций. Доступность функции зависит от внедрения в вашем регионе."],"notes":"Статус «Утерян на ПВЗ» запускался поэтапно. Сроки и наличие функции необходимо проверять в актуальной версии WB ПВЗ.","quiz":[{"q":"При выдаче товар не находится. Какая функция предусмотрена в пилотном процессе?","options":["«Не могу найти» в проверке товаров","«Выдать все» без товара","«Возврат картона»","«Новый клиент» WB Track"],"answer":0,"explanation":"«Не могу найти» в проверке товаров. Сверьте ответ с порядком действий, разобранным выше."},{"q":"При выдаче товар не найден. Какой предусмотренный сценарий использовать, если он доступен?","options":["«Не могу найти» в «Проверке товаров»","Сразу отменить весь заказ вручную","Выдать другой товар с похожим названием"],"answer":0,"explanation":"Функция «Не могу найти» запускает учёт поиска потерянного товара."},{"q":"Товар с отметкой «Утерян на ПВЗ» нашли через несколько часов. Что сделать?","options":["Передать клиенту без сканирования","Повторно отсканировать через предусмотренный сценарий приёмки","Положить на прежнюю ячейку и ничего не менять"],"answer":1,"explanation":"Повторная приёмка найденного товара восстанавливает корректный учёт."},{"q":"Товар не найден при выдаче, а в программе доступна функция «Не могу найти». Что делать?","options":["Подтвердить выдачу","Применить предусмотренный сценарий поиска/отметки отсутствия, не выдавая товар","Отметить товар как брак без осмотра","Перенести в коробку WB MP"],"answer":1,"explanation":"Нельзя подтверждать выдачу физически отсутствующего товара; доступность специального статуса зависит от версии и ПВЗ."},{"q":"Можно ли гарантировать, что статус «Утерян на ПВЗ» доступен в каждом ПВЗ?","options":["Да, он есть в любой версии","Нет, функция внедрялась поэтапно","Да, если включён WB Track","Да, если в ПВЗ есть сейф-пакеты"],"answer":1,"explanation":"Этот сценарий запускался поэтапно, поэтому наличие функции нужно проверять."}],"role":"Сотрудник","version":"","when":"Статус «Утерян на ПВЗ» и 48 часов на поиск.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n2","cat":"Нестандартные ситуации","title":"Нет интернета: что работает","summary":"Приёмка и выдача в офлайне; возвраты только онлайн.","steps":["При нестабильной связи попробуйте доступный Wi-Fi.","В офлайн-режиме приложения WB ПВЗ поддерживаются приёмка и выдача товаров.","После восстановления интернета статусы синхронизируются; списание оплаты происходит автоматически согласно инструкции от 5 мая 2026.","Возвраты из дома, подготовка возвратов, возвратные коробки, операции WB MP в разделе возвратов, картон и утиль требуют интернета.","После восстановления связи проверьте статусы выполненных операций."],"notes":"Не переносите правила офлайн-работы на сторонние сервисы и WB Track без отдельного подтверждения.","quiz":[{"q":"Пропал интернет в ПВЗ. Что делать с операциями?","options":["Проверить доступные офлайн-функции и не подтверждать несостоявшиеся действия","Считать все операции выполненными","Стереть локальную историю","Выдавать всё без проверки"],"answer":0,"explanation":"Проверить доступные офлайн-функции и не подтверждать несостоявшиеся действия. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Приёмка и выдача в офлайне; возвраты только онлайн.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n3","cat":"Расходные материалы","title":"Клиентские пакеты: выдача и учёт","summary":"Учитывайте каждый выданный пакет, контролируйте остатки.","steps":["При выдаче укажите в WB ПВЗ тип и количество выданных пакетов.","Если пакет выдан после завершения заказа, повторно отсканируйте QR-код клиента.","По опубликованному правилу — не более двух пакетов каждого типа: майка, средний и большой.","В новых версиях система учитывает фактические остатки; при нуле выбор недоступен.","Храните пакеты рядом со стойкой так, чтобы выдачу было удобно контролировать.","Если пакеты закончились и автозаказ не поступил, создайте тикет «Автоматический заказ пакетов»."],"notes":"Пакеты-майки поступают чаще; средние и большие зависят от наличия на складе.","quiz":[{"q":"Клиент просит пакеты после выдачи заказа. Что важно?","options":["Повторно отсканировать клиентский QR и учесть тип и количество","Отдать без отражения в программе","Использовать QR другого клиента","Заменить пакеты на TRBX"],"answer":0,"explanation":"Повторно отсканировать клиентский QR и учесть тип и количество. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Учитывайте каждый выданный пакет, контролируйте остатки.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n4","cat":"Поставки продавцов","title":"WB MP: приёмка от продавца","summary":"Отличайте WB MP от FBW и DBS.","steps":["Попросите продавца подготовить запечатанную со всех сторон коробку с WB-MP стикером. Каждая товарная единица внутри должна быть отдельно упакована и иметь собственный стикер.","Проверьте габариты: каждая сторона коробки не больше 80 см, сумма длины, ширины и высоты не больше 140 см, общая масса коробки с содержимым не больше 25 кг.","Принимайте товары только в присутствии продавца. Сканируйте каждую позицию, сверяйте фактическое количество и данные программы.","Если упаковка, маркировка или количество не соответствуют требованиям, не оформляйте фиктивную приёмку: предложите продавцу исправить нарушение.","После проверки добавьте товары в поток WB MP, не смешивая с обычными возвратами. Подготовьте отдельную возвратную коробку WB MP по TRBX.","Продавец должен присутствовать при приёмке WB MP. Проверьте коробку, маркировку WB-MP и отдельную наклейку на каждом индивидуально упакованном товаре.","Актуальные ограничения из присланных обновлений: не более 25 кг для каждого товара и всей коробки с содержимым; каждая сторона коробки до 80 см, сумма трёх измерений до 140 см.","Сканируйте каждую позицию при продавце. Не применяйте устаревшие ограничения 5 кг, 500 товаров в день или 60 × 40 см."],"notes":"При задержке вывоза и переполнении ПВЗ используйте тикет «Приёмка МП → Вывоз МП-коробок».","quiz":[{"q":"Продавец принёс WB MP. Что проверяют при приёмке?","options":["Упаковку, наклейки на товарах и коробке в присутствии продавца","Только телефон продавца","Наличие клиентского QR на выдачу","Настройку голосового помощника"],"answer":0,"explanation":"Упаковку, наклейки на товарах и коробке в присутствии продавца. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Продавец принёс коробку WB MP массой 24 кг, но одна сторона 90 см. Принимать?","options":["Да, масса не превышена","Нет, одна сторона превышает 80 см","Да, если товаров меньше пяти"],"answer":1,"explanation":"Для WB MP каждая сторона коробки должна быть не более 80 см, даже при допустимой массе."},{"q":"Продавец принёс коробку WB MP без индивидуальных стикеров на товарах. Как действовать?","options":["Принять коробку по одному общему стикеру","Попросить исправить маркировку до приёмки","Самостоятельно выдумать стикеры товара"],"answer":1,"explanation":"Каждая товарная единица должна быть индивидуально упакована и промаркирована."},{"q":"Продавец WB MP принёс коробку с товарами. Как принимать?","options":["Принять без продавца и отсканировать позже","Проверить коробку и индивидуальную маркировку, сканируя товары в присутствии продавца","Открыть обычную коробку для брака","Считать только количество коробок без сканирования"],"answer":1,"explanation":"Приёмка WB MP предполагает контроль упаковки, маркировки и сканирование при продавце."},{"q":"Какое ограничение массы указано для коробки WB MP вместе с содержимым?","options":["До 5 кг","До 15 кг","До 25 кг","До 40 кг"],"answer":2,"explanation":"По более поздним материалам суммарная масса коробки WB MP и её содержимого — не более 25 кг."}],"role":"Сотрудник","version":"","when":"Отличайте WB MP от FBW и DBS.","check":"До завершения приёмки сверяйте количество, индивидуальные наклейки и упаковку с тем, что показывает программа. Продавец должен присутствовать."},{"id":"n5","cat":"Поставки продавцов","title":"WB MP: возвратная коробка TRBX","summary":"Общая коробка для разных продавцов, но отдельно от обычных возвратов.","steps":["Откройте вкладку «Возврат» → «WB MP». Этот раздел не равен вкладке «Коробки» для обычных возвратов.","Создайте пустую возвратную коробку WB MP и прикрепите к ней TRBX. До добавления товара отсканируйте TRBX согласно подсказке программы.","Сканируйте каждую принятую от продавца позицию и проверяйте, что она добавлена именно в открытую коробку WB MP.","В одну коробку разрешено объединять позиции от разных продавцов при соблюдении правил программы. Одновременно можно создать не более трёх возвратных коробок WB MP.","Перед передачей перевозчику закройте коробку по требованиям программы. Водитель сканирует один TRBX для каждой коробки.","Возвратная коробка WB MP не является обычной возвратной коробкой. Создайте отдельную коробку и назначьте ей TRBX до наполнения.","В одной коробке допускается объединять товары разных продавцов при соблюдении правил. Одновременно можно создавать не более трёх таких коробок.","При передаче водитель должен сканировать TRBX каждой коробки."],"notes":"Возвратные коробки WB MP не являются обычными возвратными коробками ПВЗ. Для передачи перевозчику ориентируйтесь на отдельный сценарий отгрузки и QR перевозчика.","quiz":[{"q":"Что отличает возвратную коробку WB MP?","options":["Отдельный TRBX и отдельный процесс от обычных возвратов","Обязательное смешивание с браком","Отсутствие маркировки","Использование QR клиента"],"answer":0,"explanation":"Отдельный TRBX и отдельный процесс от обычных возвратов. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Где создаётся коробка для возврата товаров WB MP?","options":["«Возврат» → «Коробки»","«Возврат» → «WB MP»","«Доставки» → «Коробки»"],"answer":1,"explanation":"Для WB MP существует отдельный поток и собственная вкладка."},{"q":"Сколько одновременно создаваемых возвратных коробок WB MP допускает описанный процесс?","options":["Две","Три","Пять"],"answer":1,"explanation":"Для WB MP действует лимит трёх одновременно создаваемых коробок."},{"q":"Какой подход верен для возвратной коробки WB MP?","options":["Смешать с обычной коробкой возвратов","Использовать отдельный процесс WB MP и соответствующий TRBX","Использовать коробку WB Track","Не сканировать TRBX"],"answer":1,"explanation":"Возвраты WB MP учитываются отдельно от обычных возвратов и WB Track."},{"q":"В одну возвратную коробку WB MP собираются товары разных продавцов. Допустимо ли это?","options":["Нет, всегда отдельная коробка на продавца","Да, если соблюдены правила сканирования и упаковки","Только если это WB Track","Только без наклеек"],"answer":1,"explanation":"Согласно присланным материалам, товары нескольких продавцов могут объединяться в одной коробке WB MP."}],"role":"Сотрудник","version":"","when":"Общая коробка для разных продавцов, но отдельно от обычных возвратов.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n6","cat":"Поставки продавцов","title":"WB MP: передача перевозчику","summary":"Проверяйте QR-код перевозчика при вывозе коробок.","steps":["В разделе «Отгрузка товаров» покажите QR-код перевозчику.","Убедитесь в своём присутствии, что перевозчик его отсканировал.","После подтверждения назначенного вывоза передайте коробки по штатному процессу."],"notes":"QR перевозчика не заменяет наклейку TRBX на возвратной коробке.","quiz":[{"q":"Перевозчик забирает WB MP. Как подтвердить передачу?","options":["Проверить предусмотренный QR перевозчика и сканирование TRBX","Отдать без проверки","Оформить как выдачу покупателю","Поменять номер телефона"],"answer":0,"explanation":"Проверить предусмотренный QR перевозчика и сканирование TRBX. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Проверяйте QR-код перевозчика при вывозе коробок.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n7","cat":"Поставки продавцов","title":"FBW: приёмка коробок продавца","summary":"Приёмка FBW без вскрытия и сканирования каждого товара.","steps":["Попросите продавца предъявить заранее сформированные и промаркированные коробки FBW. Сверьте количество коробок с документами продавца.","В соответствующем сценарии приёмки отсканируйте номер транспортной накладной WB-GI и QR-код каждой коробки.","Всю приёмку проводите в присутствии продавца и в зоне видеонаблюдения. Коробки не вскрывайте и товары поштучно не пересчитывайте: в этом потоке принимаются именно коробки.","Если количество не совпадает, нажмите «Назад» → «Прервать», попросите продавца исправить расхождение и начните процесс заново. Частичная приёмка не предусмотрена.","Завершайте операцию только после подтверждения всех коробок в программе. Возможность FBW вводилась поэтапно и зависит от доступности функции.","При поставке FBW продавец заранее формирует и маркирует коробки. Принимайте поставку при продавце и в зоне видимости камеры.","Отсканируйте ТТН WB-GI и коды каждой коробки; вскрывать их и пересчитывать отдельные товары при такой приёмке не требуется.","При расхождении количества вернитесь назад и выберите «Прервать». Продавец должен исправить поставку, после чего процесс начинается заново. Частичную приёмку не оформляйте."],"notes":"Функция запускалась поэтапно; ограничения из отсутствующих карточек не додумываем.","quiz":[{"q":"При FBW количество коробок не совпало с заявленным. Как поступить?","options":["Прервать приёмку, дождаться исправления и начать заново","Оформить частичную приёмку","Подписать без проверки","Вскрыть и принять часть товаров"],"answer":0,"explanation":"Прервать приёмку, дождаться исправления и начать заново. Сверьте ответ с порядком действий, разобранным выше."},{"q":"При FBW число коробок не совпало с накладной. Как действовать?","options":["Принять часть и попросить донести остальное","Прервать приёмку, исправить расхождение и начать заново","Принять все, указав количество со слов продавца"],"answer":1,"explanation":"Частичная приёмка FBW не предусмотрена: «Назад» → «Прервать», затем повторный процесс."},{"q":"Нужно ли открывать каждую FBW-коробку и пересчитывать товары?","options":["Да, всегда","Только при маленькой поставке","Нет, проверяют маркированные коробки"],"answer":2,"explanation":"При FBW принимают коробки по QR-кодам без вскрытия и поштучного пересчёта."},{"q":"При приёмке FBW фактическое количество коробок не совпало с ТТН. Что делать?","options":["Подтвердить частичную приёмку","Прервать приёмку и попросить продавца устранить расхождение","Списать недостающие коробки","Оформить выдачу клиенту"],"answer":1,"explanation":"При несовпадении количества коробок предусмотрено прерывание операции, а не частичное подтверждение."},{"q":"Нужно ли вскрывать каждую коробку FBW и проверять отдельные товары?","options":["Да, всегда","Нет, в этом сценарии проверяют маркировку и коробки, не вскрывая товарные вложения","Да, если продавец торопится","Только после выдачи"],"answer":1,"explanation":"В присланном сценарии FBW сканируют ТТН и коробки в присутствии продавца без вскрытия товарных вложений."}],"role":"Сотрудник","version":"","when":"Приёмка FBW без вскрытия и сканирования каждого товара.","check":"Убедитесь, что число отсканированных коробок совпадает с заявленным в ТТН. При расхождении приёмку прерывают, а не подтверждают частично."},{"id":"n8","cat":"Поставки продавцов","title":"DBS: товары от продавца","summary":"Продавец привозит товар в тот же ПВЗ, где его заберёт покупатель.","steps":["Отличайте DBS от WB MP: DBS — это доставка товара продавцом непосредственно в ПВЗ покупателя.","Принимайте заранее упакованные товары через предусмотренный процесс DBS в приложении.","Выдавайте клиенту и оформляйте возвраты в соответствии с отдельными инструкциями DBS.","DBS — отдельный процесс: продавец привозит упакованный товар в тот ПВЗ, где его должен получить покупатель.","Для работы с ним откройте «Приёмка» → «DBS» и действуйте по подсказкам программы; не оформляйте DBS как обычную складскую поставку."],"notes":"Точные экраны и исключения изучайте в соответствующих инструкциях; нельзя переносить алгоритм FBW или MP на DBS.","quiz":[{"q":"Продавец привёз DBS-товар для покупателя. Куда перейти?","options":["«Приёмка» → «DBS»","«Возврат» → «Картон»","«Доставки» → «Коробки»","«Выдача» → «Сертификаты»"],"answer":0,"explanation":"«Приёмка» → «DBS». Сверьте ответ с порядком действий, разобранным выше."},{"q":"Где находится приёмка DBS в десктоп-приложении?","options":["«Приёмка» → «DBS»","«Возврат» → «Картон»","«Выдача» → «Из отмены»","«Доставки» → «Коробки»"],"answer":0,"explanation":"DBS представлен отдельным пунктом в меню «Приёмка»."},{"q":"В чём особенность DBS в описанном сценарии?","options":["Товар отправляется из ПВЗ только на склад WB","Продавец привозит заказ в ПВЗ, где покупатель затем его забирает","Это всегда возврат из дома","Это разновидность коробки WB Track"],"answer":1,"explanation":"DBS предусматривает поступление упакованного заказа продавца в ПВЗ для последующей выдачи покупателю."}],"role":"Сотрудник","version":"","when":"Продавец привозит товар в тот же ПВЗ, где его заберёт покупатель.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n9","cat":"Приёмка и возвраты","title":"Шины и отмена категории «Запрещённый к поставке товар»","summary":"Не отмечайте шины браком только из-за категории.","steps":["Категория «Запрещённый к поставке товар» убрана из процессов ПВЗ с июня 2026.","Шины принимайте как обычный товар; брак отмечайте только при фактическом дефекте.","Для возврата шины как КГТ снимите старый ШК-стикер и наклейте новый.","В программе выберите возвратную коробку, наклейте её стикер на шину; физически в коробку шину не кладите.","Не перекрывайте наклейками маркировку прослеживаемости."],"notes":"Это не отменяет отдельные запреты на вложения в WB Track. Для QR-кода по ШК товара WB доступен бесплатный специализированный генератор в боте: t.me/edholod_wbbot.","quiz":[{"q":"В поставке шины или особая категория. Что важно?","options":["Сверить применимые ограничения и актуальную процедуру в программе","Автоматически считать любой товар запрещённым","Скрыть категорию товара","Переклеить ШК другого товара"],"answer":0,"explanation":"Сверить применимые ограничения и актуальную процедуру в программе. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Не отмечайте шины браком только из-за категории.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n10","cat":"Приёмка и возвраты","title":"Возврат в неповреждённом сейф-пакете","summary":"Не вскрывайте целый сейф-пакет без необходимости.","steps":["Проверьте, что сейф-пакет полностью целый, не вскрывался, не протекает и содержимое не вызывает подозрений.","Если упаковка целая, оформите предусмотренный сценарий «Возврат без упаковки» без вскрытия сейф-пакета.","Новый стикер наклейте поверх старого так, чтобы прежний код не считывался. Отсканируйте новый код и положите товар в подходящую возвратную коробку.","Если содержимое повреждено, разлито или сейф-пакет вскрыт, не применяйте упрощённый сценарий: проверьте товар, оформите брак при наличии оснований и упакуйте по требованиям.","Если сейф-пакет цел и товар не повреждён, не вскрывайте его без необходимости.","В предусмотренном процессе выберите «Возврат без упаковки», закройте старую наклейку новой, отсканируйте новый код и поместите товар в подходящую возвратную коробку.","Если пакет повреждён или содержимое пролито, осмотрите товар, оформите отметку брака при наличии оснований и переупакуйте согласно правилам."],"notes":"Не путайте сохранение целого сейф-пакета с оформлением брака. Для QR-кода по ШК товара WB доступен бесплатный специализированный генератор в боте: t.me/edholod_wbbot.","quiz":[{"q":"Товар возвращают в целом сейф-пакете. Что делать?","options":["Сохранить пакет целым и оформить возврат с новой наклейкой","Обязательно вскрыть неповреждённый пакет","Наклеить новый код рядом со старым без закрытия","Отправить без сканирования"],"answer":0,"explanation":"Сохранить пакет целым и оформить возврат с новой наклейкой. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Возврат пришёл в целой запечатанной сейф-упаковке. Как действовать?","options":["Открыть упаковку для обязательного осмотра содержимого","Использовать предусмотренный возврат без вскрытия и переклеить код","Положить в коробку со старым читаемым кодом"],"answer":1,"explanation":"Для целой упаковки предусмотрен возврат без вскрытия с новым стикером поверх старого."},{"q":"Сейф-пакет явно протекает. Можно ли оформить его как целый?","options":["Нет, нужно проверить состояние и оформить брак при наличии оснований","Да, если старый стикер целый","Да, если товар не дорогой"],"answer":0,"explanation":"Протечка исключает упрощённый сценарий возврата целого пакета."},{"q":"Товар вернулся в целой, неповреждённой заводской сейф-упаковке. Какой сценарий указан в инструкции?","options":["Вскрыть упаковку в любом случае","Оформить «Возврат без упаковки», не вскрывая целый сейф-пакет, и заменить наклейку","Оформить WB Track","Поместить в утилизацию"],"answer":1,"explanation":"Для целой герметичной упаковки предусмотрено сохранение пломбы и замена маркировки по указанному сценарию."},{"q":"Сейф-пакет явно повреждён, товар протёк. Что делать?","options":["Не вскрывать и отправить как целый","Проверить содержимое, отметить дефект и упаковать по соответствующим правилам","Скрыть повреждение новой наклейкой","Выдать товар следующему клиенту"],"answer":1,"explanation":"При видимом повреждении упаковки и товара нужен осмотр и оформление дефекта."}],"role":"Сотрудник","version":"","when":"Не вскрывайте целый сейф-пакет без необходимости.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n11","cat":"Приёмка и возвраты","title":"Обувь: проверка и возврат","summary":"Проверяйте пару, коробку и правильную упаковку.","steps":["Проверьте обувь и коробку на дефекты и соответствие заказу.","Если всё цело, поместите обувь вместе с коробкой в новый сейф-пакет.","Если коробка не входит даже в самый большой сейф-пакет, закрепите крышку резинками или скотчем.","Зачеркните старый стикер, нанесите новый и подготовьте к возврату.","При фактическом дефекте отметьте брак и следуйте соответствующему процессу."],"notes":"","quiz":[{"q":"Возвращают обувь с коробкой. Что проверить?","options":["Состояние обуви, коробки и надёжность упаковки","Только размер обуви","Только цвет коробки","Только номер примерочной"],"answer":0,"explanation":"Состояние обуви, коробки и надёжность упаковки. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Проверяйте пару, коробку и правильную упаковку.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n12","cat":"Брак и подмены","title":"Запах как признак брака","summary":"Посторонний запах может быть основанием для отметки дефекта.","steps":["При приёмке, выдаче, возврате от курьера и подготовке к возврату обращайте внимание на нехарактерный запах товара.","Если запах свидетельствует о дефекте, выберите соответствующий тип брака.","При выявлении дефекта во время подготовки возврата оформите его как брак, а не как обычную подготовку."],"notes":"Не приравнивайте любой запах к доказанной подмене.","quiz":[{"q":"У товара необычный резкий запах. Как поступить?","options":["Оценить его как возможный признак брака в предусмотренной проверке","Игнорировать любой запах","Всегда считать подменой","Автоматически оформить выдачу"],"answer":0,"explanation":"Оценить его как возможный признак брака в предусмотренной проверке. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Посторонний запах может быть основанием для отметки дефекта.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n13","cat":"Брак и подмены","title":"Бренд не совпадает: это не всегда подмена","summary":"Несовпадение бренда само по себе не доказывает подмену.","steps":["Сравните бренд на товаре, упаковке и в карточке заказа.","Проверьте наличие пометки «Оригинал» и другие доступные признаки.","Не ставьте отметку «Подмена» исключительно из-за различия названий брендов.","При подтверждённом несоответствии действуйте по официальному алгоритму."],"notes":"Дополнительные критерии из карточек новости не представлены.","quiz":[{"q":"Бренд на вещи отличается от карточки. Какой вывод правильный?","options":["Это повод для проверки, но не автоматическое доказательство подмены","Это всегда подмена","Это всегда заводской брак","Это всегда основание для утилизации"],"answer":0,"explanation":"Это повод для проверки, но не автоматическое доказательство подмены. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Несовпадение бренда само по себе не доказывает подмену.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n14","cat":"Брак и подмены","title":"Бракованные товары: специальные коробки","summary":"Тестовая функция возвратных коробок для брака.","steps":["В подключённых ПВЗ коробка для брака может оставаться открытой до 6 дней.","Закройте её раньше, если набралось 10 ШК или коробка заполнена.","По истечении 6 дней предусмотрено автоматическое закрытие.","Пока коробка открыта, по условиям теста не формируются «Зависшие ШК» и удержания из-за её открытого статуса.","Крупногабаритный брак оформляйте отдельной коробкой: сохраните упаковку, наклейте новый стикер, сразу закройте и отправьте."],"notes":"Пилотный функционал: не распространяйте его автоматически на все ПВЗ. Особые сроки закрытия коробок с браком относятся к пилотным условиям и не являются универсальным правилом.","quiz":[{"q":"Для крупногабаритного бракованного товара предусмотрен отдельный процесс. Что важно?","options":["Оформить отдельную коробку для брака по действующим условиям пилота","Смешать с WB MP","Положить в коробку WB Track","Выдать клиенту"],"answer":0,"explanation":"Оформить отдельную коробку для брака по действующим условиям пилота. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Тестовая функция возвратных коробок для брака.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n15","cat":"Брак и подмены","title":"Отметку брака поставили случайно","summary":"Как отменить незавершённую отметку о браке.","steps":["На ПК: «Возврат → Товары → карточка → Дополнить / снять брак → Нет → подтверждение».","На телефоне: «Вернуть → три точки рядом с товаром → Снять отметку брака → Да, отменить».","Отменить можно только частично оформленную отметку; завершённую — нельзя этим способом.","Для возвратов из дома с одобренным заявлением о браке действует другой порядок.","Для снятия ошибочной частичной отметки брака в десктоп-приложении откройте «Возврат» → «Товары», найдите карточку и выберите «Дополнить / снять брак».","Выберите «Нет» и подтвердите изменение. Для уже согласованного возврата из дома могут действовать ограничения."],"notes":"После снятия ошибочной отметки можно продолжить обычную подготовку к возврату.","quiz":[{"q":"Сотрудник ошибочно отметил частичный брак. Где исправить?","options":["«Возврат» → «Товары» → «Дополнить / снять брак»","«Доставки» → «Новый клиент»","«Выдача» → «Подарочные сертификаты»","«Ещё» → «Смена ПВЗ»"],"answer":0,"explanation":"«Возврат» → «Товары» → «Дополнить / снять брак». Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как отменить незавершённую отметку о браке.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n16","cat":"Выдача заказов","title":"IMEI смартфонов при выдаче и возврате","summary":"Проверка IMEI Apple/Samsung от 40 000 ₽ в рамках запуска.","steps":["При выдаче подходящих устройств Apple и Samsung стоимостью от 40 000 ₽ программа может предложить проверку IMEI. Уточните согласие клиента на проверку.","Зафиксируйте состояние заводской упаковки до вскрытия, затем дайте клиенту открыть её самостоятельно.","Сверьте IMEI устройства с данными в программе, не активируя устройство до покупки. При несовпадении следуйте сценарию программы и фиксируйте доказательства.","При возврате из дома IMEI проверяется в обязательном порядке по описанному процессу. Дополнительно проверьте, что устройство сброшено до заводских настроек.","Проверку проводите в зоне камер. Учтите, что функция вводилась поэтапно и её доступность зависит от версии и категории."],"notes":"В июле 2026 функция запускалась для Apple и Samsung стоимостью от 40 000 ₽; перечень может изменяться. Проверка IMEI внедрялась поэтапно и применяется к указанным программой товарам. Следуйте актуальным подсказкам.","quiz":[{"q":"Проверяется IMEI подходящего смартфона. Что важно?","options":["Сверить IMEI по предусмотренному процессу и согласованию клиента","Считать любой IMEI подходящим","Активировать смартфон до покупки","Заменить IMEI на номер заказа"],"answer":0,"explanation":"Сверить IMEI по предусмотренному процессу и согласованию клиента. Сверьте ответ с порядком действий, разобранным выше."},{"q":"При проверке IMEI смартфона номер не совпадает с данными заказа. Что делать?","options":["Продолжить выдачу, если клиент согласен","Зафиксировать несоответствие и действовать по сценарию программы","Изменить номер вручную в карточке товара"],"answer":1,"explanation":"Несовпадение IMEI требует фиксации и корректного решения в программе."},{"q":"Как поступить с проверкой IMEI при возврате из дома по описанному процессу?","options":["Проверить IMEI и заводской сброс устройства","Проверить только целостность пакета","Пропустить проверку, если клиент торопится"],"answer":0,"explanation":"Для подходящих устройств при возврате из дома требуется проверка IMEI и заводского сброса."},{"q":"При выдаче смартфона программа предлагает проверку IMEI. Как поступить?","options":["Пропустить все проверки","Следовать сценарию программы, проверять IMEI при согласии клиента и под камерой","Активировать устройство за клиента","Сверить только цвет упаковки"],"answer":1,"explanation":"Проверка IMEI применяется к указанным товарам и выполняется по подсказкам программы с учётом согласия клиента."},{"q":"Можно ли считать проверку IMEI обязательной для каждого товара во всех ПВЗ?","options":["Да, для любого товара","Нет, функция внедрялась поэтапно и применяется к определённым товарам","Да, только для одежды","Да, если заказ оплачен"],"answer":1,"explanation":"Правила проверки зависят от категории товара и внедрения функции."}],"role":"Сотрудник","version":"","when":"Проверка IMEI Apple/Samsung от 40 000 ₽ в рамках запуска.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n17","cat":"Выдача заказов","title":"Товары «Не требует проверки»","summary":"Экспериментальный упрощённый процесс для отдельных товаров.","steps":["Если программа показывает «Не требует проверки», дополнительная проверка на камеру перед примеркой/покупкой не требуется.","Для некоторых клиентов отображается значок золотой звезды — это отдельный признак доступности упрощённых возвратов.","При отказе после примерки оформляйте фактический брак или подмену корректно, если они есть.","Для электроники, красоты и ювелирных изделий продолжает применяться «Требует проверки» согласно публикации."],"notes":"Тестовый режим: следуйте подсказкам конкретного заказа, не распространяйте на весь ассортимент. Исключение «Не требует проверки» относится только к товарам, которые программа прямо так обозначила.","quiz":[{"q":"Товар помечен «Не требует проверки». Что делать?","options":["Следовать указанному для него процессу, не распространяя исключение на другие категории","Считать все товары освобождёнными от проверки","Игнорировать явные повреждения","Удалить отметку из программы"],"answer":0,"explanation":"Следовать указанному для него процессу, не распространяя исключение на другие категории. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Экспериментальный упрощённый процесс для отдельных товаров.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n18","cat":"Выдача заказов","title":"Проверка возраста через MAX","summary":"Цифровой ID как один из способов подтверждения 18+.","steps":["При выдаче товара 18+ программа покажет запрос подтверждения возраста.","Клиент может предъявить допустимый документ или цифровой ID в MAX.","Зелёная подсказка означает, что возраст подтверждён и товар 18+ можно выдать.","При неподтверждённом возрасте товары 18+ снимаются с выдачи, остальные товары можно выдать.","Если в заказе есть неотказные товары 18+, снимите весь заказ с примерки и предложите вернуться с документом до окончания хранения.","Отказные товары 18+ уходят в отмену; согласно публикации их можно забрать в течение 24 часов, если они ещё не в возвратной коробке.","При ошибке QR MAX повторите сканирование или используйте другой допустимый способ проверки."],"notes":"Список допустимых документов был в карточках и здесь не приводится. Доступность подтверждения возраста через MAX зависит от действующего сценария и настроек программы.","quiz":[{"q":"Программа требует подтверждения возраста через MAX. Как действовать?","options":["Выполнить предусмотренную в программе проверку возраста","Использовать QR другого клиента","Игнорировать возрастное ограничение","Оформить как возврат картона"],"answer":0,"explanation":"Выполнить предусмотренную в программе проверку возраста. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Цифровой ID как один из способов подтверждения 18+.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n19","cat":"Выдача заказов","title":"Старый QR-код покупателя","summary":"Ошибка «Неизвестное отсканированное значение».","steps":["Если QR клиента не считывается и программа сообщает «Неизвестное отсканированное значение», попросите обновить клиентское приложение Wildberries.","Попросите показать новый QR-код и отсканируйте его повторно.","Если обновить приложение не удаётся, предложите прийти позднее."],"notes":"Номера минимальных версий из старых новостей не считаем актуальными.","quiz":[{"q":"QR-код покупателя не принимается. Что предложить?","options":["Обновить клиентское приложение Wildberries и показать новый QR","Ввести случайный код","Взять QR у другого покупателя","Считать заказ выданным"],"answer":0,"explanation":"Обновить клиентское приложение Wildberries и показать новый QR. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Ошибка «Неизвестное отсканированное значение».","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n20","cat":"Выдача заказов","title":"Выдача перед закрытием","summary":"Клиента, пришедшего за пять минут до закрытия, нужно обслужить.","steps":["Если клиент пришёл за 5 минут до закрытия в рабочее время, примите его.","Обеспечьте предусмотренные действия: выдачу, проверку, примерку и отказ.","Не отказывайте в обслуживании только потому, что до закрытия осталось мало времени."],"notes":"Не утверждаем конкретную обязательную длительность работы после закрытия: она не указана в новости.","quiz":[{"q":"Покупатель пришёл за 5 минут до закрытия. Что делать?","options":["Обслужить в рабочее время, включая предусмотренную примерку и отказ","Отказать только из-за близкого закрытия","Закрыть ПВЗ раньше","Отметить заказ выданным без товара"],"answer":0,"explanation":"Обслужить в рабочее время, включая предусмотренную примерку и отказ. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Клиента, пришедшего за пять минут до закрытия, нужно обслужить.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n21","cat":"Дополнительные услуги","title":"Физические подарочные сертификаты","summary":"Приёмка, хранение, выдача и тестовое пополнение.","steps":["Сертификаты поступают как расходные материалы; при приёмке сканируйте ШК на упаковке с картами.","Сертификат состоит из пластиковой карты и подарочного конверта.","Несколько конвертов можно разместить у стойки; карты и остальные конверты храните отдельно.","При выдаче вложите карту в конверт; заклеивать его не требуется.","Пополнение физического сертификата в ПВЗ запускалось как тест в Москве, области, Санкт-Петербурге и Ленинградской области только для подключённых точек."],"notes":"Цена 50 ₽ указана на 2 июня 2026 и может измениться; шаги пополнения были только в карточках.","quiz":[{"q":"Клиент предъявил физический подарочный сертификат. Что важно?","options":["Проверить его по предусмотренной функции сертификатов","Считать его обычным TRBX","Отсканировать как товар DBS","Заменить на QR курьера"],"answer":0,"explanation":"Проверить его по предусмотренной функции сертификатов. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Приёмка, хранение, выдача и тестовое пополнение.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n22","cat":"Приёмка и возвраты","title":"Утилизация: товар уже отсутствует","summary":"Как закрыть позицию в разделе «Утиль».","steps":["Если товар уже физически выведен из оборота, но продолжает числиться в программе, завершите операцию.","На ПК: «Возврат → Утиль → галочка на карточке → Утилизировать → Подтвердить».","На телефоне: «Ждут утилизации», затем аналогичные действия.","Не используйте операцию для списания физически присутствующего товара без законного основания."],"notes":"Для QR-кода по ШК товара WB доступен бесплатный специализированный генератор в боте: t.me/edholod_wbbot.","quiz":[{"q":"Товар числится в процессе утилизации, но физически отсутствует. Что делать?","options":["Разобраться в статусе и фактическом наличии до подтверждения","Подтвердить уничтожение отсутствующего товара","Заменить его другим товаром","Оформить как выдачу клиенту"],"answer":0,"explanation":"Разобраться в статусе и фактическом наличии до подтверждения. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Как закрыть позицию в разделе «Утиль».","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n23","cat":"Поддержка и безопасность","title":"Поддержка: тикеты и «Помощник»","summary":"Уведомления, оценки и ответы бота.","steps":["Об ответе в тикете или чате «Помощник» сообщает уведомление «Вам сообщение».","Через 2 часа после ответа может прийти уведомление «Поставьте оценку».","После оценки можно оставить комментарий до 200 символов.","На тикеты отвечают как операторы, так и бот-помощник.","Проверяйте, решает ли ответ проблему, и при необходимости продолжайте обращение доступным способом."],"notes":"Ответ бота не означает автоматического разрешения спорной ситуации.","quiz":[{"q":"Нужно решить вопрос через поддержку. Что подготовить?","options":["Точные данные операции и относящиеся к случаю доказательства","Чужой ПИН-код","Только эмоции без фактов","Случайный скрин другого ПВЗ"],"answer":0,"explanation":"Точные данные операции и относящиеся к случаю доказательства. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Уведомления, оценки и ответы бота.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n24","cat":"Поддержка и безопасность","title":"Оспаривание оценки 1–2","summary":"Важны 48 часов и положительное решение по обращению.","steps":["Оценки 1 и 2 первые 48 часов имеют нулевой вес согласно новости от 26 июня.","Чтобы избежать влияния оценки, подайте тикет на оспаривание в пределах 48 часов.","Одной подачи тикета недостаточно: оспаривание должно быть удовлетворено."],"notes":"Учитывайте возможные изменения сроков в актуальной оферте. Срок и условия влияния оценок на рейтинг могут меняться. Для оспаривания ориентируйтесь на действующие сроки в WB Point.","quiz":[{"q":"Пришла оценка 1–2 звезды. Как не пропустить срок оспаривания?","options":["Проверить основание и подать обоснованное оспаривание в течение 48 часов","Ждать неделю перед обращением","Попросить клиента удалить аккаунт","Менять оценку вручную"],"answer":0,"explanation":"Проверить основание и подать обоснованное оспаривание в течение 48 часов. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Важны 48 часов и положительное решение по обращению.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n25","cat":"Поддержка и безопасность","title":"Защита от мошенников","summary":"Не доверяйте внешним ссылкам и запросам кодов.","steps":["Покупки, доставку и возвраты оформляйте через официальный сайт или приложение WB.","Не сообщайте СМС-коды, паспортные данные и реквизиты карт посторонним.","Не переходите по ссылкам из подозрительных сообщений и не оплачивайте заказы по внешним ссылкам.","Не переводите обсуждение заказа в сторонние мессенджеры по просьбе неизвестных.","Акции проверяйте в официальных сервисах, вакансии — на career.rwb.ru."],"notes":"Пять схем из карточек публикации не воспроизводим: карточки не предоставлены.","quiz":[{"q":"Вам прислали ссылку с просьбой ввести код авторизации. Что делать?","options":["Не вводить код и проверить запрос через официальные каналы","Отправить код собеседнику","Переслать ПИН-код","Открыть доступ к учётной записи"],"answer":0,"explanation":"Не вводить код и проверить запрос через официальные каналы. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Не доверяйте внешним ссылкам и запросам кодов.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n26","cat":"Дополнительные услуги","title":"WB Track: ограничения и возвраты","summary":"Отдельные правила доставки WB Track.","steps":["Максимальная масса отправления WB Track по публикации — 15 кг.","Отправление должно помещаться в самый большой сейф-пакет; крупногабаритные вложения не принимаются.","Возвратная коробка WB Track создаётся на завершающем этапе приёмки отправления, отдельно её не создают.","При повреждении в пути клиент оформляет заявку в приложении WB в разделе «Возврат товара» с описанием и фотографиями.","Для WB Track указано ограничение по массе до 15 кг; отправление должно помещаться в самый большой допустимый сейф-пакет. Крупногабаритные отправления не принимаются.","Коробка WB Track создаётся на заключительном этапе приёмки. Не путайте её с обычными возвратными коробками WB ПВЗ."],"notes":"Не переносите эти правила на обычные заказы и поставки WB MP.","quiz":[{"q":"Клиент принёс посылку WB Track массой 18 кг. Что делать?","options":["Не принимать: указанное ограничение — 15 кг","Принять как обычный WB Track","Оформить как возврат картона","Положить в коробку WB MP"],"answer":0,"explanation":"Не принимать: указанное ограничение — 15 кг. Сверьте ответ с порядком действий, разобранным выше."},{"q":"Какой предельный вес посылки WB Track указан в учебных материалах?","options":["10 кг","15 кг","25 кг","40 кг"],"answer":1,"explanation":"В присланных материалах WB Track указан предел 15 кг."},{"q":"Как оформляются коробки WB Track?","options":["Через обычный возврат WB MP","В отдельном разделе WB Track «Коробки»","В разделе «Картон»","Через генератор стикеров"],"answer":1,"explanation":"У WB Track собственный учёт посылок и коробок."}],"role":"Сотрудник","version":"","when":"Отдельные правила доставки WB Track.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n27","cat":"Расходные материалы","title":"Наклейки: регистрация рулонов","summary":"Учёт рулонов и работа с повреждёнными стикерами.","steps":["Если в вашем ПВЗ включена регистрация рулонов, откройте соответствующий раздел в WB ПВЗ.","Рулон привязывается к ПВЗ, чтобы избежать дублирования наклеек между пунктами.","Если регистрационный стикер повреждён, используйте два соседних читаемых стикера.","Повреждённую наклейку при работе пропустите.","Если рулон частично использован, для регистрации предусмотрены первый, второй и последний оставшиеся стикеры.","Новые возвратные стикеры могут быть меньше и без фирменного оформления. При переходе допускаются старые и новые наклейки.","Проверяйте читаемость кода и соответствие регистрационных данных; внешний вид сам по себе не делает наклейку недействительной."],"notes":"В июне регистрация была добровольной; не утверждаем, что это актуально сегодня.","quiz":[{"q":"Новая возвратная наклейка меньше старой и без логотипа. Это ошибка?","options":["Нет, оба варианта могут использоваться при переходе","Да, все маленькие наклейки недействительны","Да, нужен только старый дизайн","Да, товар следует утилизировать"],"answer":0,"explanation":"Нет, оба варианта могут использоваться при переходе. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Учёт рулонов и работа с повреждёнными стикерами.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n28","cat":"Приёмка и возвраты","title":"Работа с возвратными коробками","summary":"Перемещение излишков между открытыми коробками.","steps":["Во вкладке «Возврат» → «Коробки» найдите действующие коробки и их типы. Открытая коробка принимает товары, закрытая — уже нет.","Для обычного возврата, брака и WB MP предусмотрены разные потоки. Не перемещайте товар между ними без соответствующей операции в программе.","При заполнении коробки проверьте её содержимое по ШК и своевременно закройте. Для пилотных коробок брака может действовать срок до шести дней или закрытие при 10 ШК/заполнении.","Для негабаритного бракованного товара предусмотрена отдельная коробка с новым стикером и немедленным закрытием в рамках пилотного сценария.","Для обычных возвратов используйте «Возврат» → «Коробки». Разделы «Все товары», «Для брака» и «Для МП-товаров» нельзя смешивать.","В пилоте коробка с браком может оставаться открытой до шести дней и закрываться раньше при наполнении или достижении 10 ШК; не переносите пилотное правило на все ПВЗ без подтверждения."],"notes":"","quiz":[{"q":"Какую коробку использовать для WB MP?","options":["Отдельную коробку «Для МП-товаров»","Обычную коробку для брака","Коробку WB Track","Коробку для картона"],"answer":0,"explanation":"Отдельную коробку «Для МП-товаров». Сверьте ответ с порядком действий, разобранным выше."},{"q":"Сотрудник хочет положить WB MP товар в обычную возвратную коробку. Допустимо?","options":["Да, если коробка ещё открыта","Нет, это разные возвратные потоки","Да, если наклеить второй TRBX"],"answer":1,"explanation":"WB MP учитывается отдельно от обычных возвратов."},{"q":"Коробка имеет статус «Закрыта». Как добавить в неё товар?","options":["Никак, нужно использовать подходящую открытую коробку","Можно добавить физически без учёта","Нужно стереть TRBX и написать новый"],"answer":0,"explanation":"Закрытую коробку нельзя пополнять без соответствующей системной операции."}],"role":"Сотрудник","version":"","when":"Перемещение излишков между открытыми коробками.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."},{"id":"n29","cat":"Начало смены","title":"Тайм-менеджмент в ПВЗ","summary":"Работа с очередью и прерываниями.","steps":["При очереди обслуживайте клиентов последовательно, не пытайтесь одновременно вести несколько выдач.","Если задачу пришлось прервать, зафиксируйте текущий статус и следующее действие.","Пример записи: «Сделать фото брака» или «В процессе».","Возвращайтесь к незавершённым операциям после устранения срочного прерывания."],"notes":"Основано на материалах корпоративного обучения RWB.","quiz":[{"q":"Во время приёмки сотрудника отвлёк клиент. Что поможет избежать ошибки?","options":["Зафиксировать текущий этап и вернуться к незавершённой операции","Подтвердить приёмку без проверки","Считать всю поставку принятой","Смешать товары разных процессов"],"answer":0,"explanation":"Зафиксировать текущий этап и вернуться к незавершённой операции. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Работа с очередью и прерываниями.","check":"Проверьте, что рабочее место готово и выбран правильный пункт выдачи."},{"id":"n30","cat":"Полезные инструменты","title":"QR-код товара WB: полезный инструмент","summary":"Бесплатный специализированный генератор QR по штрихкоду товара WB.","steps":["В Telegram-боте «Всё о WB PVZ by @edholod» доступен отдельный инструмент для формирования QR-кода стикера товара Wildberries.","Откройте соответствующий раздел бота, введите предусмотренные данные и сформируйте QR-код.","Перед использованием проверьте, что данные относятся к нужному товару. Не подменяйте этим инструментом обязательные системные операции и маркировку WB."],"notes":"Откройте бот: https://t.me/edholod_wbbot","quiz":[{"q":"Для чего в боте нужен генератор QR-кода товара WB?","options":["Для создания специализированного QR по ШК товара в допустимых сценариях","Для замены ПИН-кода сотрудника","Для генерации клиентского QR выдачи","Для регистрации TRBX перевозчика"],"answer":0,"explanation":"Для создания специализированного QR по ШК товара в допустимых сценариях. Сверьте ответ с порядком действий, разобранным выше."}],"role":"Сотрудник","version":"","when":"Бесплатный специализированный генератор QR по штрихкоду товара WB.","check":"После выполнения сравните фактический результат с отображаемым статусом в программе. При расхождении не подтверждайте операцию повторно вслепую."}],"scenarios":[{"title":"Товар не находится на полке","tag":"Поиск","steps":["Проверьте статус и ячейку по ШК","Осмотрите соседние ячейки и возвратные коробки","Не подтверждайте выдачу отсутствующего товара","Если проблема не решена — оформите предусмотренное обращение"],"lesson":"l8"},{"title":"Клиент передумал после отказа","tag":"Выдача","steps":["Проверьте срок 24 часа","Убедитесь, что товар не упакован в закрытую коробку","Используйте «Выдать из отмены», если функция доступна"],"lesson":"l14"},{"title":"Клиент отменил заказ на примерке","tag":"Выдача","steps":["Проверьте статус «Нельзя выдать»","Не выдавайте и не возвращайте до решения системы","После изменения статуса действуйте по программе"],"lesson":"l13"},{"title":"Не привезли товар со склада","tag":"Зависшие ШК","steps":["Подготовьте видео прибытия и вскрытия коробки, приёмки и пустой коробки","Оспорьте удержание в течение 7 дней","Ответьте на запрос поддержки в течение 48 часов"],"lesson":"l27"},{"title":"Водитель не забрал возврат","tag":"Логистика","steps":["Зафиксируйте коробки и факт невывоза на камеру","Откройте «Вопросы по логистике»","Выберите тему «Не забирают возвратные коробки/картон»"],"lesson":"l42"},{"title":"Обнаружен брак или подмена","tag":"Брак","steps":["Зафиксируйте состояние и расхождения под камерой","Отметьте проблему в программе","Сохраните записи для возможного оспаривания"],"lesson":"l25"},{"title":"Курьер вернул не все товары","tag":"Курьер","steps":["Просканируйте только реально возвращённые позиции","Не отмечайте отсутствующие товары принятыми","Оформите расхождение штатным способом"],"lesson":"l31"},{"title":"Клиент ушёл без оплаты","tag":"Оплата","steps":["Проверьте статус заказа","Создайте тикет «Проблема с оплатой»","Передайте видеодоказательства в течение 24 часов"],"lesson":"l15"},{"title":"Товар не найден при выдаче","tag":"Потеряшки","steps":["Проверьте ячейку и соседние места","При наличии кнопки «Не могу найти» установите статус","Продолжайте поиск до 48 часов","Если найдёте, повторно примите товар сканированием"],"lesson":"n1"},{"title":"Отключился интернет","tag":"Сбой связи","steps":["Проверьте доступность Wi-Fi","Продолжайте приёмку и выдачу в офлайн-режиме WB ПВЗ","Отложите операции возвратов до появления связи","После восстановления проверьте синхронизацию"],"lesson":"n2"},{"title":"Продавец привёз FBW с неверным числом коробок","tag":"FBW","steps":["Не принимайте часть коробок","«Назад → Прервать»","Попросите продавца исправить количество","Повторите сканирование с WB-GI"],"lesson":"n7"},{"title":"Клиент без паспорта покупает 18+","tag":"Возраст","steps":["Предложите подтверждение допустимым документом или цифровым ID MAX","Если возраст не подтверждён, не выдавайте 18+","Остальные товары выдайте, если это допускает процесс","Учтите отдельное правило для неотказных 18+"],"lesson":"n18"},{"title":"Закончились пакеты","tag":"Расходники","steps":["Проверьте остатки и учёт выдачи","Если автозаказ не поступил, создайте тикет «Автоматический заказ пакетов»","Продолжайте отмечать фактическую выдачу пакетов"],"lesson":"n3"},{"title":"Нужно получить QR по штрихкоду WB","tag":"Инструменты","steps":["Откройте Telegram-бот «Всё о WB PVZ by @edholod»","Выберите специализированный генератор товарных QR WB","Не заменяйте обязательную официальную маркировку самодельным кодом"],"lesson":"n29"}]};